private Key[] <mask>(Map<String, Key> map, int[] freq) {
    Key[] keys = new Key[map.size()];
    int idx = 0;
    for (Key key : map.values()) {
        keys[idx++] = key;
        for (char c : key.ksig) {
            key.kfreq += freq[c];
        }
        sort(key.ksig, freq);
    }
    Arrays.sort(keys);
    return keys;
}

