private void sort(char[] arr, int[] freq) {
    for (int i = 1; i < arr.length; i++) {
        for (int j = i; j > 0; j--) {
            if (freq[arr[j]] < freq[arr[j - 1]]) {
                char tmp = arr[j];
                arr[j] = arr[j - 1];
                arr[j - 1] = tmp;
            } else {
                break;
            }
        }
    }
}

