public synchronized void stop(boolean forcibly) {
    LOGGER.info("Shutting down node '{}'", name);
    if (process != null) {
        ProcessUtils.stopHandle(process.toHandle(), forcibly);
        ProcessReaper.instance().unregister(getServiceName());
    }
    deletePortsFiles();
}

public static ProcessReaper instance() {
    return INSTANCE;
}

private String getServiceName() {
    return baseWorkingDir.getFileName() + "-" + name;
}

public void deletePortsFiles() {
    try {
        Path hostsFile = workingDir.resolve("config").resolve("unicast_hosts.txt");
        Path httpPortsFile = workingDir.resolve("logs").resolve("http.ports");
        Path transportPortsFile = workingDir.resolve("logs").resolve("transport.ports");
        Path remoteClusterServerPortsFile = workingDir.resolve("logs").resolve("remote_cluster.ports");

        Files.deleteIfExists(hostsFile);
        Files.deleteIfExists(httpPortsFile);
        Files.deleteIfExists(transportPortsFile);
        Files.deleteIfExists(remoteClusterServerPortsFile);
    } catch (IOException e) {
        throw new UncheckedIOException("Failed to write unicast_hosts for: " + this, e);
    }
}

public String getName() {
    return name;
}

protected void waitUntilReady() {
    writeUnicastHostsFile();
    try {
        WaitForHttpResource wait = configureWaitForReady();
        wait.waitFor(CLUSTER_UP_TIMEOUT.toMillis());
    } catch (Exception e) {
        throw new RuntimeException("An error occurred while checking cluster '" + name + "' status.", e);
    }
}

private void writeUnicastHostsFile() {
    String transportUris = execute(() -> nodes.parallelStream().map(Node::getTransportEndpoint).collect(Collectors.joining("\n")));
    execute(() -> nodes.parallelStream().forEach(node -> {
        try {
            if (node.getSpec().getPlugins().containsKey("discovery-ec2")) {



                LOGGER.info("Skipping writing unicast hosts file for node {}", node.getName());
                return;
            }
            Path hostsFile = node.getConfigDir().resolve("unicast_hosts.txt");
            LOGGER.info("Writing unicast hosts file {} for node {}", hostsFile, node.getName());
            Files.writeString(hostsFile, transportUris);
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to write unicast_hosts for: " + node, e);
        }
    }));
}

private WaitForHttpResource configureWaitForReady() throws MalformedURLException {
    Node node = nodes.get(0);
    boolean securityEnabled = Boolean.parseBoolean(node.getSpec().getSetting("xpack.security.enabled", "true"));
    boolean sslEnabled = Boolean.parseBoolean(node.getSpec().getSetting("xpack.security.http.ssl.enabled", "false"));
    boolean securityAutoConfigured = isSecurityAutoConfigured(node);
    String scheme = securityEnabled && (sslEnabled || securityAutoConfigured) ? "https" : "http";
    WaitForHttpResource wait = new WaitForHttpResource(scheme, node.getHttpAddress(), nodes.size());
    User credentials = node.getSpec().getUsers().get(0);
    wait.setUsername(credentials.getUsername());
    wait.setPassword(credentials.getPassword());
    if (sslEnabled) {
        configureWaitSecurity(wait, node);
    } else if (securityAutoConfigured) {
        wait.setCertificateAuthorities(node.getWorkingDir().resolve("config/certs/http_ca.crt").toFile());
    }

    return wait;
}

public boolean waitFor(long durationInMs) throws GeneralSecurityException, InterruptedException, IOException {
    final long waitUntil = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(durationInMs);
    final long sleep = Long.max(durationInMs / 10, 100);

    final SSLContext ssl;
    final KeyStore trustStore = buildTrustStore();
    if (trustStore != null) {
        ssl = createSslContext(trustStore);
    } else {
        ssl = null;
    }
    IOException failure = null;
    while (true) {
        try {
            checkResource(ssl);
            return true;
        } catch (IOException e) {
            logger.debug("Failed to access resource [{}]", url, e);
            failure = e;
        }
        if (System.nanoTime() < waitUntil) {
            Thread.sleep(sleep);
        } else {
            throw failure;
        }
    }
}

