private void seizeCapacity(boolean allowOverdraft) {



    if (currentContext.isKeyOccupied()) {
        return;
    }














    drainInflightRecords(maxInFlightRecordNum, !allowOverdraft);
    inFlightRecordNum.incrementAndGet();
}

