public void <mask>(byte[] buffer, int offset, int length)
        throws IOException
{
    while (offset < length) {
        int result = read(buffer, offset, length - offset);
        if (result < 0) {
            throw new OrcCorruptionException(orcDataSourceId, "Unexpected end of stream");
        }
        offset += result;
    }
}

