void remove(K key) {
    CompletableFuture<Entry<K, V>> future;
    writeLock.lock();
    try {
        if (map == null) {
            future = null;
        } else {
            future = map.remove(key);
            if (map.isEmpty()) {
                map = null;
            }
        }
    } finally {
        writeLock.unlock();
    }
    if (future != null) {
        evictions.increment();
        notifyWithInvalidated(future);
    }
}

