public static double normalizeLat(double lat) {
    if (lat > 90d || lat < -90d) {
        lat = centeredModulus(lat, 360);
        if (lat < -90) {
            lat = -180 - lat;
        } else if (lat > 90) {
            lat = 180 - lat;
        }
    }

    return lat + 0d;
}

public static double centeredModulus(double dividend, double divisor) {
    double rtn = dividend % divisor;
    if (rtn <= 0) {
        rtn += divisor;
    }
    if (rtn > divisor / 2) {
        rtn -= divisor;
    }
    return rtn;
}

