public static char[] toHexCharArray(byte[] bytes) {
    Objects.requireNonNull(bytes);
    final char[] result = new char[2 * bytes.length];
    for (int i = 0; i < bytes.length; i++) {
        byte b = bytes[i];
        result[2 * i] = HEX_DIGITS[b >> 4 & 0xf];
        result[2 * i + 1] = HEX_DIGITS[b & 0xf];
    }
    return result;
}

