public long readLong() throws IOException {
    if (position >= 0 && position < this.end - 7) {
        @SuppressWarnings("restriction")
        long value = UNSAFE.getLong(this.buffer, BASE_OFFSET + this.position);
        if (LITTLE_ENDIAN) {
