public boolean forceComplete() {

    if (completed) {
        return false;
    }

    lock.lock();
    try {

        if (!completed) {
            completed = true;

            cancel();
            onComplete();
            return true;
        } else {
            return false;
        }
    } finally {
        lock.unlock();
    }
}

