private InProgressFileWriter<IN, String> <mask>(long currentTime) throws IOException {
    closePartFile();

    final Path partFilePath = assembleNewPartPath();

    if (LOG.isDebugEnabled()) {
        LOG.debug(
                "Opening new part file \"{}\" for bucket id={}.",
                partFilePath.getName(),
                bucketId);
