public void <mask>(byte[] dst, int offset, int len) throws IOException {
    int toRead = len;
    while (true) {
        final int left = buffer.remaining();
        if (left < toRead) {
            buffer.get(dst, offset, left);
            toRead -= left;
            offset += left;
            refill(toRead);
        } else {
            buffer.get(dst, offset, toRead);
            break;
        }
    }
}

