private void growCapacity()
{
    int newSize;
    if (initialized) {
        newSize = BlockUtil.calculateNewArraySize(valueIsNull.length);
    }
    else {
        newSize = initialEntryCount;
        initialized = true;
    }

    valueIsNull = Arrays.copyOf(valueIsNull, newSize);
    offsets = Arrays.copyOf(offsets, newSize + 1);
    updateDataSize();
}

static int calculateNewArraySize(int currentSize)
{

    long newSize = (long) currentSize + (currentSize >> 1);


    if (newSize < DEFAULT_CAPACITY) {
        newSize = DEFAULT_CAPACITY;
    }
    else if (newSize > MAX_ARRAY_SIZE) {
        newSize = MAX_ARRAY_SIZE;
        if (newSize == currentSize) {
            throw new IllegalArgumentException(format("Can not grow array beyond '%s'", MAX_ARRAY_SIZE));
        }
    }
    return (int) newSize;
}

private void updateDataSize()
{
    retainedSizeInBytes = INSTANCE_SIZE + sizeOf(valueIsNull) + sizeOf(offsets);
    if (blockBuilderStatus != null) {
        retainedSizeInBytes += BlockBuilderStatus.INSTANCE_SIZE;
    }
}

public void addBytes(int bytes)
{
    currentSize += bytes;
    pageBuilderStatus.addBytes(bytes);
}

void addBytes(int bytes)
{
    if (bytes < 0) {
        throw new IllegalArgumentException("bytes cannot be negative");
    }
    currentSize += bytes;
}

