        Thread.currentThread().interrupt();
        throw new IOException("interrupted");
    }
}

private void closeAndUploadPart() throws IOException {
    fileStream.flush();
    fileStream.close();
    if (fileStream.getPos() > 0L) {
        upload.uploadPart(fileStream);
    }
    fileStream.release();
}

