public double <mask>(Corpus corpus, TextTerms doc, String[] terms, int[] tf, int n) {
    int N = corpus.docCount();
    int docSize = doc.size();
    int avgDocSize = corpus.avgDocSize();

    double r = 0.0;
    for (int i = 0; i < terms.length; i++) {
