    double[] bound = MathEx.colMax(lines[0].points);
    for (int k = 1; k < lines.length; k++) {
        for (double[] x : lines[k].points) {
            for (int i = 0; i < x.length; i++) {
                if (bound[i] < x[i]) {
                    bound[i] = x[i];
                }
            }
        }
    }

    return bound;
}

