    final double lat = tileToLat((double) yTile, tiles);
    if (tiles < MAX_TILES_FULL_PRECISION || yTile == 0 || yTile == tiles) {
        return lat; 
    }

    final double qLat = quantizeLat(lat);
    final int computedYTile = getYTile(qLat, tiles);



