public void propagateDropout() {
    if (dropout > 0.0) {
        Vector output = this.output.get();
        byte[] mask = this.mask.get();
        double scale = 1.0 / (1.0 - dropout);
        for (int i = 0; i < n; i++) {
            byte retain = (byte) (MathEx.random() < dropout ? 0 : 1);
            mask[i] = retain;
            output.mul(i, retain * scale);
        }
    }
}

