public void writeByte(byte value)
{
    checkState(!closed);


    if (size == SEQUENCE_BUFFER_SIZE) {
        flushSequence();
    }


    if (value == lastValue) {
        runCount++;
    }
    else {

        if (runCount >= MIN_REPEAT_SIZE) {
            flushSequence();
        }
        runCount = 1;
    }


    sequenceBuffer[size] = value;
    size++;


    if (runCount == MIN_REPEAT_SIZE && size > MIN_REPEAT_SIZE) {

        size -= MIN_REPEAT_SIZE;
        runCount = 0;

        flushSequence();


        runCount = MIN_REPEAT_SIZE;
        size = MIN_REPEAT_SIZE;



    }

    lastValue = value;
}

@Override
public void close()
{
    closed = true;
    if (size != 0) {
        flushSequence();
    }
    buffer.close();
}

private void flushSequence()
{
    if (runCount >= MIN_REPEAT_SIZE) {
        buffer.writeByte(runCount - MIN_REPEAT_SIZE);
        buffer.writeByte(lastValue);
    }
    else {
        buffer.writeByte(-size);
        if (size == 1) {
            buffer.writeByte(sequenceBuffer[0]);
        }
        else {
            buffer.writeBytes(sequenceBuffer, 0, size);
        }
    }

    size = 0;
    runCount = 0;
    lastValue = UNMATCHABLE_VALUE;
}

@Override
public void close()
{
    flushBufferToOutputStream();
}

