public static int dot(int[] a, int[] b) {
    int sum = 0;

    for (int p1 = 0, p2 = 0; p1 < a.length && p2 < b.length; ) {
        int i1 = a[p1];
        int i2 = b[p2];
        if (i1 == i2) {
            sum++;
            p1++;
            p2++;
        } else if (i1 > i2) {
            p2++;
        } else {
            p1++;
        }
    }

    return sum;
}

