        String path = ".";
        Path localDir = Paths.get(path);
        if (!Files.isDirectory(localDir.resolve("db"))
                || !Files.isDirectory(localDir.resolve("lang"))) {
            try {
                Path sourceLocation =
                        Paths.get(
