@Override
public void skip(int length)
{
    int remaining = length;
    while (remaining > 0 && bufOffset < bufEnd) {
        int size = BytesUtils.getInt(buffer, bufOffset);
        bufOffset += (4 + size);
        remaining--;
    }
    checkState(remaining == 0, "Invalid read size request");
}

public static int getInt(byte[] byteBuffer, int offset)
{
    int ch0 = byteBuffer[offset + 0] & 255;
    int ch1 = byteBuffer[offset + 1] & 255;
    int ch2 = byteBuffer[offset + 2] & 255;
    int ch3 = byteBuffer[offset + 3] & 255;

    return (ch3 << 24) + (ch2 << 16) + (ch1 << 8) + ch0;
}

