protected void run() throws IOException {
    exitCode = 0; 
    runCommand();
}

private void runCommand() throws IOException {
    ProcessBuilder builder = new ProcessBuilder(execString());
    Timer timeoutTimer = null;
    completed = new AtomicBoolean(false);

    process = builder.start();
    if (timeout > -1) {
        timeoutTimer = new Timer();

        timeoutTimer.schedule(new ShellTimeoutTimerTask(this), timeout);
    }
    final BufferedReader errReader = new BufferedReader(
        new InputStreamReader(process.getErrorStream(), StandardCharsets.UTF_8));
    BufferedReader inReader = new BufferedReader(
        new InputStreamReader(process.getInputStream(), StandardCharsets.UTF_8));
    final StringBuffer errMsg = new StringBuffer();



    Thread errThread = KafkaThread.nonDaemon("kafka-shell-thread", () -> {
        try {
            String line = errReader.readLine();
            while ((line != null) && !Thread.currentThread().isInterrupted()) {
                errMsg.append(line);
                errMsg.append(System.lineSeparator());
                line = errReader.readLine();
            }
        } catch (IOException ioe) {
            LOG.warn("Error reading the error stream", ioe);
        }
    });
    errThread.start();

    try {
        parseExecResult(inReader); 

        exitCode = process.waitFor();
        try {

            errThread.join();
        } catch (InterruptedException ie) {
            LOG.warn("Interrupted while reading the error stream", ie);
        }
        completed.set(true);


        if (exitCode != 0) {
            throw new ExitCodeException(exitCode, errMsg.toString());
        }
    } catch (InterruptedException ie) {
        throw new IOException(ie.toString());
    } finally {
        if (timeoutTimer != null)
            timeoutTimer.cancel();


        try {
            inReader.close();
        } catch (IOException ioe) {
            LOG.warn("Error while closing the input stream", ioe);
        }
        if (!completed.get())
            errThread.interrupt();

        try {
            errReader.close();
        } catch (IOException ioe) {
            LOG.warn("Error while closing the error stream", ioe);
        }

        process.destroy();
    }
}

