public static long demarshallintBig(byte[] _buf, int _ofs, int _width) {
    long l = 0;
    for (int i = 0; i < _width; i++) {
        l <<= 8;
        l |= _buf[_ofs + i] & 0xFF;
    }
    return l;
}

public static long demarshallintLittle(byte[] _buf, int _ofs, int _width) {
    long l = 0;
    for (int i = _width - 1; i >= 0; i--) {
        l <<= 8;
        l |= _buf[_ofs + i] & 0xFF;
    }
    return l;
}

