    currentWatermark = Long.MAX_VALUE;
    InternalTimer<K, N> timer;
    while ((timer = eventTimeTimersQueue.poll()) != null) {
        triggerTarget.onEventTime(timer);
    }
    while ((timer = processingTimeTimersQueue.poll()) != null) {
