    return BinaryVariantUtil.getType(value, pos);
}

public static Type getType(byte[] value, int pos) {
    checkIndex(pos, value.length);
    int basicType = value[pos] & BASIC_TYPE_MASK;
    int typeInfo = (value[pos] >> BASIC_TYPE_BITS) & TYPE_INFO_MASK;
    switch (basicType) {
        case SHORT_STR:
            return Type.STRING;
        case OBJECT:
            return Type.OBJECT;
        case ARRAY:
            return Type.ARRAY;
        default:
            switch (typeInfo) {
                case NULL:
                    return Type.NULL;
                case TRUE:
                case FALSE:
                    return Type.BOOLEAN;
                case INT1:
                    return Type.TINYINT;
                case INT2:
                    return Type.SMALLINT;
                case INT4:
                    return Type.INT;
                case INT8:
                    return Type.BIGINT;
                case DOUBLE:
                    return Type.DOUBLE;
                case DECIMAL4:
                case DECIMAL8:
                case DECIMAL16:
                    return Type.DECIMAL;
                case DATE:
                    return Type.DATE;
                case TIMESTAMP_LTZ:
                    return Type.TIMESTAMP_LTZ;
                case TIMESTAMP:
                    return Type.TIMESTAMP;
                case FLOAT:
                    return Type.FLOAT;
                case BINARY:
                    return Type.BYTES;
                case LONG_STR:
                    return Type.STRING;
                default:
                    throw unknownPrimitiveTypeInVariant(typeInfo);
            }
    }
}

public static boolean getBoolean(byte[] value, int pos) {
    checkIndex(pos, value.length);
    int basicType = value[pos] & BASIC_TYPE_MASK;
    int typeInfo = (value[pos] >> BASIC_TYPE_BITS) & TYPE_INFO_MASK;
    if (basicType != PRIMITIVE || (typeInfo != TRUE && typeInfo != FALSE)) {
        throw unexpectedType(Type.BOOLEAN);
    }
    return typeInfo == TRUE;
}

static void checkIndex(int pos, int length) {
    if (pos < 0 || pos >= length) {
        throw malformedVariant();
    }
}

