public static int decimalToOctal(int decimal) {
    int octalValue = 0;
    int placeValue = 1;

    while (decimal > 0) {
        int remainder = decimal % 8;
        octalValue += remainder * placeValue;
        decimal /= 8;
        placeValue *= 10;
    }

    return octalValue;
}

