public static int gcd(int num1, int num2) {
    if (num1 < 0 || num2 < 0) {
        throw new ArithmeticException();
    }

    if (num1 == 0 || num2 == 0) {
        return Math.abs(num1 - num2);
    }

    while (num1 % num2 != 0) {
        int remainder = num1 % num2;
        num1 = num2;
        num2 = remainder;
    }
    return num2;
}

