@Override
public BlockBuilder appendNull()
{
    if (values.length <= positionCount) {
        growCapacity();
    }

    valueIsNull[positionCount] = true;

    hasNullValue = true;
    positionCount++;
    if (blockBuilderStatus != null) {
        blockBuilderStatus.addBytes(Byte.BYTES + Integer.BYTES);
