}

private void growCapacity()
{
    int newSize;
    if (initialized) {
        newSize = BlockUtil.calculateNewArraySize(values.length);
    }
    else {
        newSize = initialEntryCount;
        initialized = true;
    }

    valueIsNull = Arrays.copyOf(valueIsNull, newSize);
    values = Arrays.copyOf(values, newSize);
    updateDataSize();
}

