public T <mask>(T element) {
    if (size < maxSize) {
        add(element);
        return null;
    } else if (size > 0 && lessThan(heap.get(1), element)) {
        T ret = heap.get(1);
        heap.set(1, element);
        updateTop();
        return ret;
    } else {
        return element;
    }
}

children.method_body:
public final T add(T element) {

    long index = size + 1;
    heap.set(index, element);
    size = index;
    upHeap(index);
    return heap.get(1);
}

private boolean upHeap(long origPos) {
    long i = origPos;
    T node = heap.get(i); 
    long j = i >>> 1;
    while (j > 0 && lessThan(node, heap.get(j))) {
        heap.set(i, heap.get(j)); 
        i = j;
        j = j >>> 1;
    }
    heap.set(i, node); 
    return i != origPos;
}

public final T updateTop() {
    downHeap(1);
    return heap.get(1);
}

private void downHeap(long i) {
    T node = heap.get(i); 
    long j = i << 1; 
    long k = j + 1;
    if (k <= size && lessThan(heap.get(k), heap.get(j))) {
        j = k;
    }
    while (j <= size && lessThan(heap.get(j), node)) {
        heap.set(i, heap.get(j)); 
        i = j;
        j = i << 1;
        k = j + 1;
        if (k <= size && lessThan(heap.get(k), heap.get(j))) {
            j = k;
        }
    }
    heap.set(i, node); 
}

