void pause() {
  PauseStartedNotifier pauseStartedNotifier = new PauseStartedNotifier();
  synchronized (lock) {
    if (state == State.PAUSED) {
      return;
    }
    checkState(state == State.UNPAUSED);

    controlQueue.add(pauseStartedNotifier);
    looperExecutor.execute(new PauseRunnable(pauseStartedNotifier));
  }
  getAndThrow(pauseStartedNotifier);
}

@Override
public void unPause() {
  if (realLooper == Looper.getMainLooper()
      && looperMode() != LooperMode.Mode.INSTRUMENTATION_TEST) {
    throw new UnsupportedOperationException("main looper cannot be unpaused");
  }
  looperControlService.unpause();
}

public static LooperMode.Mode looperMode() {
  synchronized (looperModeLock) {
    if (cachedLooperMode == null) {
      cachedLooperMode = ConfigurationRegistry.get(LooperMode.Mode.class);
    }
    return cachedLooperMode;
  }
}

void unpause() {
  checkState(looper != getMainLooper() || looperMode() == Mode.INSTRUMENTATION_TEST);
  executeControlTask(
      () -> {
        synchronized (lock) {
          checkState(
              state != State.SHUTDOWN,
              "unpause of %s failed: Looper is shutdown",
              Thread.currentThread().getName());
          state = State.UNPAUSED;
        }
      });
}

