@Override
public Iterator<Page> buildHashSortedIntermediateResult()
{
    return new ResultIterator(groupByHash.getHashSortedGroupIds(), true);
}

default IntIterator getHashSortedGroupIds()
{
    IntBigArray groupIds = new IntBigArray();
    groupIds.ensureCapacity(getGroupCount());
    for (int i = 0; i < getGroupCount(); i++) {
        groupIds.set(i, i);
    }

    groupIds.sort(0, getGroupCount(), (leftGroupId, rightGroupId) ->
            Long.compare(getRawHash(leftGroupId), getRawHash(rightGroupId)));

    return new IntIterator()
    {
        private final int totalPositions = getGroupCount();
        private int position;

        @Override
        public boolean hasNext()
        {
            return position < totalPositions;
        }

        @Override
        public int nextInt()
        {
            return groupIds.get(position++);
        }
    };
}

private void initializeInputInMemoryGroupedTopNBuilder()
{
    if (inputInMemoryGroupedTopNBuilder != null) {
        inputInMemoryGroupedTopNBuilder.close();
    }
    inputInMemoryGroupedTopNBuilder = inputInMemoryGroupedTopNBuilderSupplier.get();
