public T getOrRefresh() {
    if (needsRefresh()) {
        if (refreshLock.tryLock()) {
            try {
                if (needsRefresh()) { 
                    cached = refresh();
                    assert cached != null;
                    lastRefreshTimestamp = System.currentTimeMillis();
                }
            } finally {
                refreshLock.unlock();
            }
        }
    }
    assert cached != null;
    return cached;
}

