}

private static void sort(float[] a, int l, int r) {
    int h;
    for (h = 1; h <= (r-l)/9; h = 3*h+1);
    for (; h > 0; h /= 3) {
        for (int i = l + h; i <= r; i++) {
            int j = i;
            float v = a[i];
            while (j >= l+h && a[j-h] < v) {
                a[j] = a[j-h];
                j -= h;
                a[j] = v;
            }
        }
    }
}

