private void <mask>(Collection<TopicPartition> partitions, AutoOffsetResetStrategy offsetResetStrategy) {
    if (partitions == null)
        throw new IllegalArgumentException("Partitions collection cannot be null");

    acquireAndEnsureOpen();
    try {
        applicationEventHandler.addAndGet(new ResetOffsetEvent(
            partitions,
            offsetResetStrategy,
            defaultApiTimeoutDeadlineMs())
        );
    } finally {
        release();
    }
}

children.method_body:
private void acquireAndEnsureOpen() {
    acquire();
    if (this.closed) {
        release();
        throw new IllegalStateException("This consumer has already been closed.");
    }
}

private void acquire() {
    final Thread thread = Thread.currentThread();
    final long threadId = thread.getId();
    if (threadId != currentThread.get() && !currentThread.compareAndSet(NO_CURRENT_THREAD, threadId))
        throw new ConcurrentModificationException("KafkaConsumer is not safe for multi-threaded access. " +
            "currentThread(name: " + thread.getName() + ", id: " + threadId + ")" +
            " otherThread(id: " + currentThread.get() + ")"
        );
    refCount.incrementAndGet();
}

private void release() {
    if (refCount.decrementAndGet() == 0)
        currentThread.set(NO_CURRENT_THREAD);
}

private long defaultApiTimeoutDeadlineMs() {
    return calculateDeadlineMs(time, defaultApiTimeoutMs);
}

private void release() {
    if (refCount.decrementAndGet() == 0)
        currentThread.set(NO_CURRENT_THREAD);
}

