void writeVLongNoCheck(long i) throws IOException {
    final byte[] buffer = StreamOutputHelper.getThreadLocalScratchBuffer();
    int index = 0;
    while ((i & ~0x7F) != 0) {
        buffer[index++] = ((byte) ((i & 0x7f) | 0x80));
        i >>>= 7;
    }
    buffer[index++] = ((byte) i);
    writeBytes(buffer, 0, index);
}

