private List<ExtensionComponent<T>> ensureLoaded() {
    if (extensions != null)
        return extensions; 
    if (jenkins == null || jenkins.getInitLevel().compareTo(InitMilestone.PLUGINS_PREPARED) < 0)
        return legacyInstances; 

    synchronized (getLoadLock()) {
