public static <T> void swap(T[] array, int i, int j) {
    if (i != j) {
        final T temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

private static <T extends Comparable<T>> int findMinIndex(T[] array, final int start) {

    if (start == array.length - 1) {
        return start;
    }


    final int minIndexInRest = findMinIndex(array, start + 1);


    return SortUtils.less(array[start], array[minIndexInRest]) ? start : minIndexInRest;
}

public static <T extends Comparable<T>> boolean less(T firstElement, T secondElement) {
    return firstElement.compareTo(secondElement) < 0;
}

