public synchronized byte[] mac(byte[] message) {
    ConfidentialStore cs = ConfidentialStore.get();
    if (mac == null || cs != lastCS) {
        lastCS = cs;
        mac = createMac();
    }
    return chop(mac.doFinal(message));
}

public static @NonNull ConfidentialStore get() {
    Jenkins j = Jenkins.getInstanceOrNull();
    if (j == null) {
        return Mock.INSTANCE;
    }
    Lookup lookup = j.lookup;
    ConfidentialStore cs = lookup.get(ConfidentialStore.class);
    if (cs == null) {
        try {
            Iterator<ConfidentialStore> it = ServiceLoader.load(ConfidentialStore.class, ConfidentialStore.class.getClassLoader()).iterator();
            if (it.hasNext()) {
                cs = it.next();
            }
        } catch (ServiceConfigurationError e) {
            LOGGER.log(Level.WARNING, "Failed to list up ConfidentialStore implementations", e);

        }

        if (cs == null)
            try {
                cs = new DefaultConfidentialStore();
            } catch (Exception e) {

                throw new Error(e);
            }

        cs = lookup.setIfNull(ConfidentialStore.class, cs);
    }
    return cs;
}

public Mac createMac() {
    try {
        Mac mac = Mac.getInstance(ALGORITHM);
        mac.init(getKey());
        return mac;
    } catch (GeneralSecurityException e) {

        throw new Error(ALGORITHM + " not supported?", e);
    }
}

private byte[] chop(byte[] mac) {


    if (FIPS140.useCompliantAlgorithms() && length < mac.length) {
        throw new IllegalArgumentException("Supplied length can't be less than " + mac.length + " on FIPS mode");
    }
    if (mac.length <= length)  return mac; 

    byte[] b = new byte[length];
    System.arraycopy(mac, 0, b, 0, b.length);
    return b;
}

