public boolean isHoldMessage() {
    if (isHoldMessageImpl()) {
        return true;
    }

    synchronized (countLock) {
        countCaughtMessages--;
        if (countCaughtMessages == 0) {
            setButtonsAndIconState(false);
        }
    }
    return false;
}

private boolean isHoldMessageImpl() {
    if (step) {

        stepping = true;
        step = false;
        return false;
    }
    if (cont) {

        stepping = false;
        resetRequestSerialization(false);
        return false;
    }
    if (drop) {
        return false;
    }
    return true;
}

