public byte[] getValue() {
    if (pos == 0) {
        return value;
    }
    int size = valueSize(value, pos);
    checkIndex(pos + size - 1, value.length);
    return Arrays.copyOfRange(value, pos, pos + size);
}

public static int valueSize(byte[] value, int pos) {
    checkIndex(pos, value.length);
    int basicType = value[pos] & BASIC_TYPE_MASK;
    int typeInfo = (value[pos] >> BASIC_TYPE_BITS) & TYPE_INFO_MASK;
    switch (basicType) {
        case SHORT_STR:
            return 1 + typeInfo;
        case OBJECT:
            return handleObject(
                    value,
                    pos,
                    (size, idSize, offsetSize, idStart, offsetStart, dataStart) ->
                            dataStart
                                    - pos
                                    + readUnsigned(
                                            value,
                                            offsetStart + size * offsetSize,
                                            offsetSize));
        case ARRAY:
            return handleArray(
                    value,
                    pos,
                    (size, offsetSize, offsetStart, dataStart) ->
                            dataStart
                                    - pos
                                    + readUnsigned(
                                            value,
                                            offsetStart + size * offsetSize,
                                            offsetSize));
        default:
            switch (typeInfo) {
                case NULL:
                case TRUE:
                case FALSE:
                    return 1;
                case INT1:
                    return 2;
                case INT2:
                    return 3;
                case INT4:
                case DATE:
                case FLOAT:
                    return 5;
                case INT8:
                case DOUBLE:
                case TIMESTAMP_LTZ:
                case TIMESTAMP:
                    return 9;
                case DECIMAL4:
                    return 6;
                case DECIMAL8:
                    return 10;
                case DECIMAL16:
                    return 18;
                case BINARY:
                case LONG_STR:
                    return 1 + U32_SIZE + readUnsigned(value, pos + 1, U32_SIZE);
                default:
                    throw unknownPrimitiveTypeInVariant(typeInfo);
            }
    }
}

static void checkIndex(int pos, int length) {
    if (pos < 0 || pos >= length) {
        throw malformedVariant();
    }
}

