protected final int <mask>(byte[] bytes, int startPos, int limit, byte[] delimiter) {
    int endPos = startPos;

    final int delimLimit = limit - delimiter.length + 1;

    while (endPos < limit) {
        if (endPos < delimLimit && delimiterNext(bytes, endPos, delimiter)) {
            break;
        }
        endPos++;
    }

    if (endPos == startPos) {
        setErrorState(ParseErrorState.EMPTY_COLUMN);
        return -1;
    }
    return endPos;
}

