public static final boolean delimiterNext(byte[] bytes, int startPos, byte[] delim) {

    for (int pos = 0; pos < delim.length; pos++) {

        if (delim[pos] != bytes[startPos + pos]) {
            return false;
        }
    }
    return true;
}

