public static Color[] rainbow(int n, float start, float end, float s, float v, float alpha) {
    Color[] palette = new Color[n];
    float h = start;
    float w = (end - start) / (n - 1);
    for (int i = 0; i < n; i++) {
        palette[i] = hsb(h, s, v, alpha);
        h += w;
    }

    return palette;
}

public static Color hsb(float hue, float saturation, float brightness, float opacity) {
    float r = 0.0f;
    float g = 0.0f;
    float b = 0.0f;

    if (saturation == 0) {


        r = brightness;
        g = brightness;
        b = brightness;
    } else {
        if (hue == 1.0f) {
            hue = 0.0f;
        }


        hue *= 6;

        int i = (int) Math.floor(hue);
        float f = hue - i; 
        float p = brightness * (1 - saturation);
        float q = brightness * (1 - (saturation * f));
        float t = brightness * (1 - (saturation * (1 - f)));

        switch (i) {
            case 0:
                r = brightness;
                g = t;
                b = p;
                break;

            case 1:
                r = q;
                g = brightness;
                b = p;
                break;

            case 2:
                r = p;
                g = brightness;
                b = t;
                break;

            case 3:
                r = p;
                g = q;
                b = brightness;
                break;

            case 4:
                r = t;
                g = p;
                b = brightness;
                break;

            case 5:
                r = brightness;
                g = p;
                b = q;
                break;
        }
    }

    return new Color(r, g, b, opacity);
}

