static int <mask>(double[] x) {
    double h = Math.ceil(3.5 * MathEx.stdev(x) / Math.pow(x.length, 1.0/3));
    return bins(x, h);
}

children.method_body:
public static double stdev(double[] array) {
    return sqrt(var(array));
}

public static double var(double[] array) {
    if (array.length < 2) {
        throw new IllegalArgumentException("Array length is less than 2.");
    }

    double sum = 0.0;
    double sumsq = 0.0;
    for (double xi : array) {
        sum += xi;
        sumsq += xi * xi;
    }

    int n = array.length - 1;
    return sumsq / n - (sum / array.length) * (sum / n);
}

static int bins(double[] x, double h) {
    if (h <= 0.0) {
        throw new IllegalArgumentException("Invalid bin width: " + h);
    }

    double max = MathEx.max(x);
    double min = MathEx.min(x);

    return (int) Math.ceil((max-min) / h);
}

public static double max(double[] array) {
    double max = Double.NEGATIVE_INFINITY;

    for (double n : array) {
        if (n > max) {
            max = n;
        }
    }

    return max;
}

public static double min(double[] array) {
    double min = Double.POSITIVE_INFINITY;

    for (double n : array) {
        if (n < min) {
            min = n;
        }
    }

    return min;
}

