public double[][] apply(T[] x) {
    int m = x.length;
    double[][] y = new double[m][];
    for (int i = 0; i < m; i++) {
        y[i] = apply(x[i]);
    }
    return y;
}

@Override
public double[] apply(T x) {
    int n = data.length;

    Vector y = projection.vector(n);
    for (int i = 0; i < n; i++) {
        y.set(i, kernel.k(x, data[i]));
    }

    double my = y.mean();
    for (int i = 0; i < n; i++) {
        y.sub(i, my + mean[i] - mu);
    }

    return projection.mv(y).toArray(new double[0]);
}

