private PhysicalFilePool getOrCreateFilePool(long checkpointId) {
    synchronized (writablePhysicalFilePool) {
        PhysicalFilePool filePool = writablePhysicalFilePool.get(checkpointId);
        if (filePool == null) {
            filePool = createPhysicalPool();
            writablePhysicalFilePool.put(checkpointId, filePool);
        }
        return filePool;
    }
}

protected final PhysicalFilePool createPhysicalPool() {
    switch (filePoolType) {
        case NON_BLOCKING:
            return new NonBlockingPhysicalFilePool(
                    maxPhysicalFileSize, this::createPhysicalFile);
        case BLOCKING:
            return new BlockingPhysicalFilePool(maxPhysicalFileSize, this::createPhysicalFile);
        default:
            throw new UnsupportedOperationException(
                    "Unsupported type of physical file pool: " + filePoolType);
    }
}

public void close() throws IOException {
    innerClose();
    deleteIfNecessary();
}

private void innerClose() throws IOException {
    synchronized (this) {
        if (closed) {
            return;
        }
        closed = true;
        if (outputStream != null) {
            outputStream.close();
            outputStream = null;
        }
    }
}

public void deleteIfNecessary() throws IOException {
    synchronized (this) {
        if (!isOpen() && !deleted && this.logicalFileRefCount.get() <= 0) {
            if (outputStream != null) {
                try {
                    outputStream.close();
                } catch (IOException e) {
                    LOG.warn("Fail to close output stream when deleting file: {}", filePath);
                }
            }
            if (deleter != null && isOwned) {
                deleter.perform(filePath, size.get());
            } else {
                LOG.debug(
                        "Skip deleting this file {} because it is not owned by FileMergingManager.",
                        filePath);
            }
            this.deleted = true;
        }
    }
}

