void writeLength(int length) throws IOException {
    if (length > 127) {
        int size = 1;
        int val = length;

        while ((val >>>= 8) != 0) {
            size++;
        }

        write((byte) (size | 0x80));

        for (int i = (size - 1) * 8; i >= 0; i -= 8) {
            write((byte) (length >> i));
        }
    } else {
        write((byte) length);
    }
}

