public static LocalTime toLocalTime(int time) {
    int h = time / 3600000;
    int time2 = time % 3600000;
    int m = time2 / 60000;
    int time3 = time2 % 60000;
    int s = time3 / 1000;
    int ms = time3 % 1000;
    return LocalTime.of(h, m, s, ms * 1000_000);
}

