public void closeDriverFactoryIfFullyCreated()
{
    if (closed) {
        return;
    }
    for (Lifespan lifespan : status.getAndAcknowledgeLifespansWithNoMoreDrivers(pipelineContext.getPipelineId())) {
        driverFactory.noMoreDrivers(lifespan);
