    List<String> locales = readAvailableLocales();

    List<ViewLocale> localesUI = new ArrayList<>();
    if (!locales.isEmpty()) {
        Map<String, Long> languageCount =
                locales.stream()
                        .map(LocaleUtils::getLanguage)
                        .collect(
                                Collectors.groupingBy(
                                        Function.identity(), Collectors.counting()));
        for (String locale : locales) {
            boolean duplicatedLanguage = languageCount.get(getLanguage(locale)) != 1;
            localesUI.add(
                    new ViewLocale(locale, getLocalDisplayName(locale, duplicatedLanguage)));
        }

        Collections.sort(
                localesUI,
                new Comparator<ViewLocale>() {

                    @Override
                    public int compare(ViewLocale o1, ViewLocale o2) {
                        return o1.toString().compareTo(o2.toString());
                    }
                });
    }


    localesUI.add(0, new ViewLocale(DEFAULT_LOCALE, getLocalDisplayName(DEFAULT_LOCALE)));

    return localesUI;
}

