public static int getIndexForValue(int bucketCount, double min, double max, double value)
{
    checkArgument(
            value >= min && value < max,
            "value must be within range: %s [%s, %s]", value, min, max);
    return Math.min(
            (int) (bucketCount * (value - min) / (max - min)),
            bucketCount - 1);
}

