        TxnMetadata oldestTxnMetadata = firstEntry.getValue();
        ProducerStateEntry entry = producers.get(oldestTxnMetadata.producerId);
        oldestTxnLastTimestamp = entry != null ? entry.lastTimestamp() : -1L;
    }
