public boolean <mask>(int threadIndex, T element) throws InterruptedException {
    if (element == null) {
        throw new NullPointerException();
    }
    lock.lockInterruptibly();
    try {
        while (queue.size() >= capacity) {
            if (getAndResetWakeUpFlag(threadIndex)) {
                return false;
            }
            waitOnPut(threadIndex);
        }
        enqueue(element);
        return true;
    } finally {
        lock.unlock();
    }
}

