    if (process == 0) { 

        return run[process][machine];
    } else {

        int[] runningCosts = new int[numberMachines]; 


        for (int k = 0; k < numberMachines; k++) { 

            runningCosts[k] = cost[process - 1][k] + transfer[k][machine] + run[process][machine]; 

        }
        return findMin(runningCosts); 
    }
}

