public final T <mask>(T element) {

    long index = size + 1;
    heap.set(index, element);
    size = index;
    upHeap(index);
    return heap.get(1);
}

children.method_body:
private boolean upHeap(long origPos) {
    long i = origPos;
    T node = heap.get(i); 
    long j = i >>> 1;
    while (j > 0 && lessThan(node, heap.get(j))) {
        heap.set(i, heap.get(j)); 
        i = j;
        j = j >>> 1;
    }
    heap.set(i, node); 
    return i != origPos;
}

