public synchronized ListenableFuture<?> reserveSpill(long bytes)
{
    checkArgument(bytes >= 0, "bytes is negative");
    if (spillUsed + bytes > maxSpill) {
        throw exceededPerQueryLocalLimit(succinctBytes(maxSpill));
    }
    ListenableFuture<?> future = spillSpaceTracker.reserve(bytes);
    spillUsed += bytes;
    return future;
}

public synchronized ListenableFuture<?> reserve(long bytes)
{
    checkArgument(bytes >= 0, "bytes is negative");

    if ((currentBytes + bytes) >= maxBytes) {
        throw exceededLocalLimit(succinctBytes(maxBytes));
    }
    currentBytes += bytes;

    return NOT_BLOCKED;
}

