        long persistedCheckpoint = checkpoint.getPersistedCheckpoint();
        while (persistedCheckpoint++ < checkpoint.getProcessedCheckpoint()) {
            BulkInferenceResponseItem response = bufferedResponses.remove(persistedCheckpoint);
            if (response == null) {
