    if (closed.get() == false && locks != null) {
        synchronized (locks) {
            if (closed.get()) return; 
            for (Lock lock : locks) {
                try {
                    lock.ensureValid();
                } catch (IOException e) {
                    logger.warn("lock assertion failed", e);
                    throw new IllegalStateException("environment is not locked", e);
                }
            }
        }
    }
}

