protected File getOutputFile() {
    FileNameExtensionFilter textFilesFilter =
            new FileNameExtensionFilter(
                    Constant.messages.getString("file.format.ascii"), "txt");
    FileNameExtensionFilter htmlFilesFilter =
            new FileNameExtensionFilter(
                    Constant.messages.getString("file.format.html"), "html", "htm");
    WritableFileChooser chooser =
            new WritableFileChooser(extension.getModel().getOptionsParam().getUserDirectory()) {

                private static final long serialVersionUID = 1L;

                @Override
                public void approveSelection() {
                    File file = getSelectedFile();
                    if (file != null) {
                        String ext = null;
                        String filePath = file.getAbsolutePath();
                        String fileNameLc = filePath.toLowerCase(Locale.ROOT);
                        if (htmlFilesFilter.equals(getFileFilter())) {
                            if (!fileNameLc.endsWith(".htm") && !fileNameLc.endsWith(".html")) {
                                ext = ".html";
                            }
                        } else if (!fileNameLc.endsWith(".txt")) {
                            ext = ".txt";
                        }

                        if (ext != null) {
                            setSelectedFile(new File(filePath + ext));
                        }
                    }

                    super.approveSelection();
                }
            };

    chooser.addChoosableFileFilter(textFilesFilter);
    chooser.addChoosableFileFilter(htmlFilesFilter);
    chooser.setFileFilter(textFilesFilter);

    int rc = chooser.showSaveDialog(extension.getView().getMainFrame());
    if (rc == JFileChooser.APPROVE_OPTION) {
        return chooser.getSelectedFile();
    }
    return null;
}

public JTree getTreeSite() {
    if (treeSite == null) {
        treeSite = new JTree(new DefaultTreeModel(new DefaultMutableTreeNode()));
        treeSite.setShowsRootHandles(true);
        treeSite.setName("treeSite");
        treeSite.setToggleClickCount(1);




        LookAndFeel laf = UIManager.getLookAndFeel();
        if (laf != null
                && Constant.isMacOsX()
                && UIManager.getSystemLookAndFeelClassName().equals(laf.getClass().getName())) {
            treeSite.setRowHeight(0);
        }

        treeSite.addTreeSelectionListener(
                new javax.swing.event.TreeSelectionListener() {

                    @Override
                    public void valueChanged(javax.swing.event.TreeSelectionEvent e) {

                        SiteNode node = (SiteNode) treeSite.getLastSelectedPathComponent();
                        if (node == null) {
                            return;
                        }
                        if (!node.isRoot()) {
                            HttpMessage msg = null;
                            try {
                                msg = node.getHistoryReference().getHttpMessage();
                            } catch (Exception e1) {

                                LOGGER.warn(e1.getMessage(), e1);
                                return;
                            }

                            getView().displayMessage(msg);


                            for (SiteMapListener listener : listeners) {
                                listener.nodeSelected(node);
                            }
                        } else {

                            getView().displayMessage(null);
                        }
                    }
                });
        treeSite.setComponentPopupMenu(new SitesCustomPopupMenu());


        DefaultTreeCellRenderer renderer = new SiteMapTreeCellRenderer(listeners);
        treeSite.setCellRenderer(renderer);

        String deleteSiteNode = "zap.delete.sitenode";
        treeSite.getInputMap().put(getView().getDefaultDeleteKeyStroke(), deleteSiteNode);
        treeSite.getActionMap()
                .put(
                        deleteSiteNode,
                        new AbstractAction() {

                            private static final long serialVersionUID = 1L;

                            @Override
                            public void actionPerformed(ActionEvent e) {
                                ExtensionHistory extHistory =
                                        Control.getSingleton()
                                                .getExtensionLoader()
                                                .getExtension(ExtensionHistory.class);
                                if (extHistory == null || treeSite.getSelectionCount() == 0) {
                                    return;
                                }

                                FileConfiguration config =
                                        Model.getSingleton().getOptionsParam().getConfig();
                                boolean confirmRemoval =
                                        config.getBoolean(REMOVE_CONFIRMATION_KEY, true);

                                if (confirmRemoval) {
                                    JCheckBox removeWithoutConfirmationCheckBox =
                                            new JCheckBox(
                                                    Constant.messages.getString(
                                                            "sites.purge.confirm.message"));
                                    Object[] messages = {
                                        Constant.messages.getString("sites.purge.warning"),
                                        " ",
                                        removeWithoutConfirmationCheckBox
                                    };
                                    int result =
                                            JOptionPane.showOptionDialog(
                                                    View.getSingleton().getMainFrame(),
                                                    messages,
                                                    Constant.messages.getString(
