public boolean advanceNext() {
    checkValidity();

    try {
        updateIteratorIfNeeded();


        while (true) {
            if (currentIterator != null && (row = currentIterator.next(reuse)) != null) {
                this.nextRow++;
                return true;
            } else {
                if (!nextIterator()) {
                    return false;
                }
            }
