private static long powerModP(long x, long y, long p) {
    long res = 1; 

    x = x % p; 

    if (x == 0) {
        return 0; 
    }
    while (y > 0) {

        if ((y & 1) == 1) {
            res = multiplyModP(res, x, p);
        }


        y = y >> 1; 
        x = multiplyModP(x, x, p);
    }
    return res;
}

private static long multiplyModP(long a, long b, long p) {
