}

@Override public synchronized void write(@NonNull byte[] buf, int off, int len) {

    if (len > capacity) {
        off += len - capacity;
        len = capacity;
    }


    int num = Math.min(len, capacity - pos);
    if (num > 0) {
        System.arraycopy(buf, off, data, pos, num);
        off += num;
        len -= num;
        pos += num;
    }


    if (pos == capacity) {
        filled = true;
        pos = 0;
    }


    if (len > 0) {
        System.arraycopy(buf, off, data, pos, len);
        pos += len;
    }
}

