private <T extends Comparable<T>> void <mask>(final T[] array, final int left, final int right) {
    for (int i = left + 1; i <= right; i++) {
        T key = array[i];
        int j = i - 1;
        while (j >= left && SortUtils.greater(array[j], key)) {
            array[j + 1] = array[j];
            j--;
        }
        array[j + 1] = key;
    }
}

