protected final long readVLongSlow() throws IOException {
    byte b = readByte();
    long i = b & 0x7FL;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7FL) << 7;
    if ((b & 0x80) == 0) {
