    b = readByte();
    i |= ((b & 0x7FL) << 56);
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    if (b != 0 && b != 1) {
        throwOnBrokenVLong(b, i);
    }
    i |= ((long) b) << 63;
    return i;
}

