}

children.method_body:
static double median(double[] x) {
    int k = x.length / 2;
    return select(x, k);
}

static double select(double[] x, int k) {
    int n = x.length;
    int l = 0;
    int ir = n - 1;

    double a;
    int i, j, mid;
    for (;;) {
        if (ir <= l + 1) {
            if (ir == l + 1 && x[ir] < x[l]) {
                Sort.swap(x, l, ir);
            }
            return x[k];
        } else {
            mid = (l + ir) >> 1;
            Sort.swap(x, mid, l + 1);
            if (x[l] > x[ir]) {
                Sort.swap(x, l, ir);
            }
            if (x[l + 1] > x[ir]) {
                Sort.swap(x, l + 1, ir);
            }
            if (x[l] > x[l + 1]) {
                Sort.swap(x, l, l + 1);
            }
            i = l + 1;
            j = ir;
            a = x[l + 1];
            for (;;) {
                do {
                    i++;
                } while (x[i] < a);
                do {
                    j--;
                } while (x[j] > a);
                if (j < i) {
                    break;
                }
                Sort.swap(x, i, j);
            }
            x[l + 1] = x[j];
            x[j] = a;
            if (j >= k) {
                ir = j - 1;
            }
            if (j <= k) {
                l = i;
            }
        }
    }
}

