public boolean <mask>(int firstTypeOption,
                            int... additionalTypeOptions)
        throws IllegalStateException {
    if (completed) {
        return false;
    }
    Token current = currentToken();
    if (current.matches(firstTypeOption)) {
        return true;
    }
    for (int nextTypeOption : additionalTypeOptions) {
