public static boolean <mask>(int n, int iteration) {
    long a;
    int up = n - 2;
    int down = 2;
    for (int i = 0; i < iteration; i++) {
        a = (long) Math.floor(Math.random() * (up - down + 1) + down);
        if (modPow(a, n - 1, n) != 1) {
            return false;
        }
    }
    return true;
}

