@Override
public boolean hasMoreTokens()
{

    if (_hasToken)
        return true;

    _lastStart = _i;

    int state = 0;
    boolean escape = false;
    while (_i < _string.length())
    {
        char c = _string.charAt(_i++);

        switch (state)
        {
          case 0: 
              if (_delim.indexOf(c) >= 0)
              {
                  if (_returnDelimiters)
                  {
                      _token.append(c);
                      return _hasToken = true;
                  }
              }
              else if (c == '\'' && _single)
              {
                  if (_returnQuotes)
                      _token.append(c);
                  state = 2;
              }
              else if (c == '\"' && _double)
              {
                  if (_returnQuotes)
                      _token.append(c);
                  state = 3;
              }
              else
              {
                  _token.append(c);
                  _hasToken = true;
                  state = 1;
              }
              continue;

          case 1: 
              _hasToken = true;
              if (escape)
              {
                  escape = false;
                  if (ESCAPABLE_CHARS.indexOf(c) < 0)
                      _token.append('\\');
                  _token.append(c);
              }
              else if (_delim.indexOf(c) >= 0)
              {
                  if (_returnDelimiters)
                      _i--;
                  return _hasToken;
              }
              else if (c == '\'' && _single)
              {
                  if (_returnQuotes)
                      _token.append(c);
                  state = 2;
              }
              else if (c == '\"' && _double)
              {
                  if (_returnQuotes)
                      _token.append(c);
                  state = 3;
              }
              else if (c == '\\')
              {
                  escape = true;
              }
              else
                  _token.append(c);
              continue;


          case 2: 
              _hasToken = true;
              if (escape)
              {
                  escape = false;
                  if (ESCAPABLE_CHARS.indexOf(c) < 0)
                      _token.append('\\');
                  _token.append(c);
              }
              else if (c == '\'')
              {
                  if (_returnQuotes)
                      _token.append(c);
                  state = 1;
              }
              else if (c == '\\')
              {
                  if (_returnQuotes)
                      _token.append(c);
                  escape = true;
              }
              else
                  _token.append(c);
              continue;


          case 3: 
              _hasToken = true;
              if (escape)
              {
                  escape = false;
                  if (ESCAPABLE_CHARS.indexOf(c) < 0)
                      _token.append('\\');
                  _token.append(c);
              }
              else if (c == '\"')
              {
                  if (_returnQuotes)
                      _token.append(c);
                  state = 1;
              }
              else if (c == '\\')
              {
                  if (_returnQuotes)
                      _token.append(c);
                  escape = true;
              }
              else
                  _token.append(c);
              continue;

          default:
              break;
        }
    }

    return _hasToken;
}

@Override
public String nextToken()
    throws NoSuchElementException
{
    if (!hasMoreTokens() || _token == null)
        throw new NoSuchElementException();
    String t = _token.toString();
    _token.setLength(0);
    _hasToken = false;
    return t;
}

