private void <mask>(int bytesWritten, boolean isNull)
{
    if (!initialized) {
        initializeCapacity();
    }
    if (valueIsNull.length <= positions) {
        growCapacity();
    }

    valueIsNull[positions] = isNull;
    offsets[positions + 1] = sliceOutput.size();

