    FakeEncodedItem[] newData = new FakeEncodedItem[newCapacity];
    dataSize = Math.min(dataSize, newCapacity);
    dataPosition = Math.min(dataPosition, dataSize);
    System.arraycopy(data, 0, newData, 0, dataSize);
    data = newData;
  }
}

