public  static <T> PlattScaling <mask>(Classifier<T> model, T[] x, int[] y) {
    int n = y.length;
    double[] scores = new double[n];
    for (int i = 0; i < n; i++) {
        scores[i] = model.score(x[i]);
    }

    return fit(scores, y);
}

