public long readIntLenenc() {
    int firstByte = readInt1();
    if (firstByte < 0xfb) {
        return firstByte;
    }
    if (0xfb == firstByte) {
        return 0L;
    }
    if (0xfc == firstByte) {
        return readInt2();
    }
    if (0xfd == firstByte) {
        return readInt3();
    }
    return byteBuf.readLongLE();
}

