public static String toHex(byte[] _buf, int _ofs, int _len, boolean _spaces) {
    StringBuilder sb = new StringBuilder();
    int j = _ofs + _len;
    for (int i = _ofs; i < j; i++) {
        if (i < _buf.length) {
            sb.append(HEX_CHARS[(_buf[i] & 0xF0) >> 4]);
            sb.append(HEX_CHARS[_buf[i] & 0x0F]);
            if (_spaces) {
                sb.append(' ');
            }
        } else {
            if (_spaces) {
                sb.append(' ');
                sb.append(' ');
                sb.append(' ');
            }
        }
    }
    return sb.toString();
}

