public boolean isRelevant() {
    switch (this.type) {
        case CORE:
            VersionNumber current = Jenkins.getVersion();
            return isRelevantToVersion(current);
        case PLUGIN:


            PluginWrapper plugin = Jenkins.get().getPluginManager().getPlugin(this.component);
