private void evict() {
    minmax();

    vectors.removeIf(v -> {
        if (MathEx.isZero(v.alpha, 1E-4)) {
            if ((v.g >= gmax && 0 >= v.cmax) || (v.g <= gmin && 0 <= v.cmin)) {
                K[v.i] = null;
                return true;
            }
        }
        return false;
    });
