public AuditTrail get() {
    if (auditTrail != null) {
        if (Security.AUDITING_FEATURE.check(licenseState)) {
            return auditTrail;
        } else {
            maybeLogAuditingDisabled();
            return NOOP_AUDIT_TRAIL;
