public static double normalizeLon(double lon) {
    if (lon > 180d || lon <= -180d) {
        lon = centeredModulus(lon, 360);
    }

    return lon + 0d;
}

public static double centeredModulus(double dividend, double divisor) {
    double rtn = dividend % divisor;
    if (rtn <= 0) {
        rtn += divisor;
    }
    if (rtn > divisor / 2) {
        rtn -= divisor;
    }
    return rtn;
}

