private void <mask>() {
    int recordCounter = 0;
    while (collectorIterator.hasNext()) {
        final T record = collectorIterator.next();
        if (allRecords.contains(record)) {
            if (matchedRecords.add(record)) {
                recordCounter++;
            }
        } else {
