public static double distance(int[] a, int[] b) {
    return sqrt(squaredDistance(a, b));
}

public static double squaredDistance(int[] a, int[] b) {
    double d = 0.0;

    int p1 = 0, p2 = 0;
    while (p1 < a.length && p2 < b.length) {
        int i1 = a[p1];
        int i2 = b[p2];
        if (i1 == i2) {
            p1++;
            p2++;
        } else if (i1 > i2) {
            d++;
            p2++;
        } else {
            d++;
            p1++;
        }
    }

    d += a.length - p1;
    d += b.length - p2;

    return d;
}

