public String toString(int m, int n) {
    StringBuilder sb = new StringBuilder();
    m = Math.min(m, nrow);
    n = Math.min(n, ncol);

    String newline = n < ncol ? "...\n" : "\n";

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            sb.append(String.format("%d  ", get(i, j)));
        }
        sb.append(newline);
    }

    if (m < nrow) {
        sb.append("  ...\n");
    }

    return sb.toString();
}

