                "--headless=new",
                "--disable-gpu",
                "--window-size=1920,1200",
                "--ignore-certificate-errors",
                "--disable-dev-shm-usage",
                "--remote-allow-origins=*",
                "--no-sandbox"
        );
    }

    return options;
}

