        this.samples.add(newSample(now));
    Sample oldest = this.samples.get(0);
    for (int i = 1; i < this.samples.size(); i++) {
        Sample curr = this.samples.get(i);
        if (curr.startTimeMs < oldest.startTimeMs)
            oldest = curr;
    }
    return oldest;
}

