                System.err.println(
                        "Failed to determine the ZAP installation dir: " + e.getMessage());
                path = localDir.toAbsolutePath().toString();
            }

            System.out.println("Defaulting ZAP install dir to " + path);
        }

        zapInstall = getAbsolutePath(path);
    }
    return zapInstall;
}

