@Override
public void close() {
    if (closed) {
        assert false : "ExponentialHistogramMerger closed multiple times";
    } else {
        closed = true;
        if (result != null) {
            factory.releaseBuffer(result);
            result = null;
        }
        factory.circuitBreaker.adjustBreaker(-BASE_SIZE);
        factory.notifyMergerClosed();
    }
}

private static long estimateBaseSize(int numBuckets) {
    return SHALLOW_SIZE + RamEstimationUtil.estimateDoubleArray(numBuckets);
};

