public E <mask>(E reuse) throws IOException {


    if (this.heap.size() > 0) {

        final HeadStream<E> top = this.heap.peek();
        E result = top.getHead();


        if (!top.nextHead(reuse)) {
            this.heap.poll();
        } else {
            this.heap.adjustTop();
        }
        return result;
    } else {
        return null;
    }
}

