    RuntimeException error = null;
    for (WriteContext context : writers) {
        try {
            if (context != null) {
                context.getWriter().rollback();
            }
        }
        catch (Throwable t) {
            if (error == null) {
                error = new RuntimeException("Exception during rollback");
            }
            error.addSuppressed(t);
        }
    }
    if (error != null) {
        throw error;
    }
}

