    for (int r = 1; r <= H3Index.H3_get_resolution(h); r++) {
        final int dir = H3Index.H3_get_index_digit(h, r);
        if (dir != CoordIJK.Direction.CENTER_DIGIT.digit()) {
            return dir;
        }
    }

    return CoordIJK.Direction.CENTER_DIGIT.digit();
}

