public void beginShutdown() {
    if (!shutdownExecutor.isShutdown()) {
        shutdownExecutor.submit((Callable<Void>) () -> {
            try {
                log.info("Stopping REST server");
                jettyServer.stop();
                jettyServer.join();
                log.info("REST server stopped");
            } catch (Exception e) {
                log.error("Unable to stop REST server", e);
            } finally {
                try {
                    jettyServer.destroy();
                } catch (Exception e) {
                    log.error("Unable to destroy REST server", e);
                }
                shutdownExecutor.shutdown();
            }
            return null;
        });
    }
}

public void beginShutdown() throws Exception {
    if (shutdownManager.shutdown()) {
        shutdownExecutor.submit(new Shutdown());
    }
