        }
        final int toRead;
        if (bufferFree < minRemainingBytes) {



            if (offsetByteArray > 0) {
                sizeByteArray = sizeByteArray - offsetByteArray;
                switch (sizeByteArray) { 
                    case 1 -> byteBuffer[0] = byteBuffer[offsetByteArray];
                    case 2 -> {
