public int getEncodedDate() {
    int cpMonth = month;
    int cpYear = year;
    if (cpMonth > 2) {
        cpMonth -= 3;
    } else {
        cpMonth += 9;
        cpYear -= 1;
    }
    int c = cpYear / 100;
    int ya = cpYear - 100 * c;
    return convertDate(c, ya, cpMonth);
}

private int convertDate(final int c, final int ya, final int cpMonth) {
    return (146097 * c) / 4
            + (1461 * ya) / 4
            + (153 * cpMonth + 2) / 5
            + day + 1721119 - 2400001;
}

