static void siftUp(float[] a, int k) {
    while (k > 1 && a[k/2] < a[k]) {
        swap(a, k, k/2);
        k = k/2;
    }
}

static void swap(float[] a, int i, int j) {
    float temp = a[i];
    a[i] = a[j];
    a[j] = temp;
}

static void siftDown(float[] a, int k, int n) {
    while (2*k <= n) {
        int j = 2 * k;
        if (j < n && a[j] < a[j + 1]) {
            j++;
        }
        if (a[k] >= a[j]) {
            break;
        }
        swap(a, k, j);
        k = j;
    }
}

static void swap(float[] a, int i, int j) {
    float temp = a[i];
    a[i] = a[j];
    a[j] = temp;
}

