    }
    b = readByte();
    i |= (b & 0x7F) << 21;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    if ((b & 0x80) != 0) {
        throwOnBrokenVInt(b, i);
    }
    return i | ((b & 0x7F) << 28);
}

