  Iterator<IdlingResourceProxyImpl> iterator = syncedIdlingResources.iterator();
  while (iterator.hasNext()) {
    IdlingResourceProxyImpl proxy = iterator.next();
    if (registeredResourceByName.get(proxy.name) == proxy.resource) {

