    }
    b = readByte();
    i |= (b & 0x7FL) << 21;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7FL) << 28;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7FL) << 35;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7FL) << 42;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7FL) << 49;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= ((b & 0x7FL) << 56);
    if ((b & 0x80) == 0) {
        return i;
