private void swim(int k) {
    while (k > 1 && less(k, (k + d - 2) / d)) {
        swap(k, (k + d - 2) / d);
        k = (k + d - 2) / d;
    }
}

private boolean less(int i, int j) {
    return a[pq[i]] < a[pq[j]];
}

private void swap(int i, int j) {
    int t = pq[i];
    pq[i] = pq[j];
    pq[j] = t;
    qp[pq[i]] = i;
    qp[pq[j]] = j;
}

private void sink(int k, int N) {
    int j;
    while ((j = d * (k - 1) + 2) <= N) {
        for (int i = j + 1; i < j + d && i <= N; i++) {
            if (less(i, j)) {
                j = i;
            }
        }
        if (!(less(j, k))) {
            break;
        }
        swap(k, j);
        k = j;
    }
}

