    return false;
}

private boolean isConsonant(int i) {
    return switch (b[i]) {
        case 'a', 'e', 'i', 'o', 'u' -> false;
        case 'y' -> i == 0 || !isConsonant(i - 1);
        default -> true;
    };
}

