            return "RECTIFIER";
        }

        @Override
        public void f(Vector x) {
            int n = x.size();
            for (int i = 0; i < n; i++) {
                x.set(i, Math.max(0.0, x.get(i)));
            }
        }

        @Override
        public void g(Vector g, Vector y) {
            int n = y.size();
            for (int i = 0; i < n; i++) {
