public static void <mask>(int n) {
    for (int i = 0; i < n; i++) {
        for (int j = -i; j <= 0; j++) {
            System.out.print(trinomialValue(i, j) + " ");
        }

        for (int j = 1; j <= i; j++) {
            System.out.print(trinomialValue(i, j) + " ");
        }

        System.out.println();
