protected final int readVIntSlow() throws IOException {
    byte b = readByte();
    int i = b & 0x7F;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7F) << 7;
    if ((b & 0x80) == 0) {
        return i;
