private static void <mask>(float[] arr, int n) {
    for (int i = n / 2; i >= 1; i--) {
        Sort.siftDown(arr, i, n);
    }
}

children.method_body:
static void siftDown(float[] a, int k, int n) {
    while (2*k <= n) {
        int j = 2 * k;
        if (j < n && a[j] < a[j + 1]) {
            j++;
        }
        if (a[k] >= a[j]) {
            break;
        }
        swap(a, k, j);
        k = j;
    }
}

static void swap(float[] a, int i, int j) {
    float temp = a[i];
    a[i] = a[j];
    a[j] = temp;
}

