private static byte[] getMacResult(final byte[] key, final byte[] data) {
    Mac mac = Mac.getInstance(MAC_REQUEST_ALGORITHM);
    mac.init(new SecretKeySpec(key, MAC_REQUEST_ALGORITHM));
