public boolean <mask>(int target) throws IOException {
    final int targetBlock = target & 0xFFFF0000;
    if (block < targetBlock) {
        advanceBlock(targetBlock);
    }
    boolean found = block == targetBlock && method.advanceExactWithinBlock(this, target);
    this.doc = target;
    return found;
}

children.method_body:
private void advanceBlock(int targetBlock) throws IOException {
    do {
        slice.seek(blockEnd);
        readBlockHeader();
    } while (block < targetBlock);
}

private void readBlockHeader() throws IOException {
    block = Short.toUnsignedInt(slice.readShort()) << 16;
    assert block >= 0;
    final int numValues = 1 + Short.toUnsignedInt(slice.readShort());
    index = nextBlockIndex;
    nextBlockIndex = index + numValues;
    if (numValues <= MAX_ARRAY_LENGTH) {
        method = Method.SPARSE;
        blockEnd = slice.getFilePointer() + (numValues << 1);
    } else if (numValues == 65536) {
        method = Method.ALL;
        blockEnd = slice.getFilePointer();
        gap = block - index - 1;
    } else {
        method = Method.DENSE;
        blockEnd = slice.getFilePointer() + (1 << 13);
        wordIndex = -1;
        numberOfOnes = index + 1;
    }
}

