}

children.method_body:
T snapshottableAddOrReplace(T object) {
    object.setStartEpoch(snapshotRegistry.latestEpoch() + 1);
    int prevSize = baseSize();
    T prev = baseAddOrReplace(object);
    if (prev == null) {
        updateTierData(prevSize);
    } else {
        updateTierData(prev, prevSize);
    }
    return prev;
}

public long latestEpoch() {
    return head.prev().epoch();
}

final int baseSize() {
    return size;
}

final T baseAddOrReplace(T newObject) {
    if (((size + 1) * MAX_LOAD_FACTOR > elements.length) &&
            (elements.length < MAX_CAPACITY)) {
        int newSize = elements.length * 2;
        rehash(newSize);
    }
    int slot = findSlot(newObject, elements.length);
    Object cur = elements[slot];
    if (cur == null) {
        size++;
        elements[slot] = newObject;
        return null;
    } else if (cur instanceof Object[]) {
        T[] curArray = (T[]) cur;
        for (int i =  0; i < curArray.length; i++) {
            T value = curArray[i];
            if (value.equals(newObject)) {
                curArray[i] = newObject;
                return value;
            }
        }
        size++;
        T[] newArray = (T[]) new Object[curArray.length + 1];
        System.arraycopy(curArray, 0, newArray, 0, curArray.length);
        newArray[curArray.length] = newObject;
        elements[slot] = newArray;
        return null;
    } else if (cur.equals(newObject)) {
        elements[slot] = newObject;
        return (T) cur;
    } else {
        size++;
        elements[slot] = new Object[] {cur, newObject};
        return null;
    }
}

private void updateTierData(int prevSize) {
    Iterator<Snapshot> iterator = snapshotRegistry.reverseIterator();
    if (iterator.hasNext()) {
        Snapshot snapshot = iterator.next();
        HashTier<T> tier = snapshot.getDelta(SnapshottableHashTable.this);
        if (tier == null) {
            tier = new HashTier<>(prevSize);
            snapshot.setDelta(SnapshottableHashTable.this, tier);
        }
    }
}

private void updateTierData(T prev, int prevSize) {
    Iterator<Snapshot> iterator = snapshotRegistry.reverseIterator();
    if (iterator.hasNext()) {
        Snapshot snapshot = iterator.next();


        if (prev.startEpoch() <= snapshot.epoch()) {
            HashTier<T> tier = snapshot.getDelta(SnapshottableHashTable.this);
            if (tier == null) {
                tier = new HashTier<>(prevSize);
                snapshot.setDelta(SnapshottableHashTable.this, tier);
            }
            if (tier.deltaTable == null) {
                tier.deltaTable = new BaseHashTable<>(1);
            }
            tier.deltaTable.baseAddOrReplace(prev);
        }
    }
}

