private void evict() {
    minmax();

    vectors.removeIf(v -> {
        if (MathEx.isZero(v.alpha, 1E-4)) {
            if ((v.g >= gmax && 0 >= v.cmax) || (v.g <= gmin && 0 <= v.cmin)) {
                K[v.i] = null;
                return true;
            }
        }
        return false;
    });
}

private void minmax() {
    if (minmaxflag) return;

    gmin = Double.MAX_VALUE;
    gmax = -Double.MAX_VALUE;

    for (SupportVector<T> v : vectors) {
        double gi = v.g;
        double ai = v.alpha;
        if (gi < gmin && ai > v.cmin) {
            svmin = v;
            gmin = gi;
        }
        if (gi > gmax && ai < v.cmax) {
            svmax = v;
            gmax = gi;
        }
    }

    minmaxflag = true;
}

