private int getAvailablePort() {
    int first = current;
    while (true) {
        current++;
        if (current > endPort) {
            current = startPort;
        }
        int candidate = current;
        if (allocated.contains(candidate) == false && portDetector.isAvailable(candidate)) {
            allocated.add(candidate);
            return candidate;
        } else {
            if (current == first) {
                return -1;
            }
        }
    }
}

