public static double deviance(int[] count, double[] prob) {
    int k = count.length;
    double d = 0.0;
    for (int i = 0; i < k; i++) {
        d -= count[i] * Math.log(prob[i]);
    }
    return 2 * d;
}

public static double[] posteriori(int[] count, double[] prob) {
    int k = count.length;
    double n = MathEx.sum(count) + k;
    for (int i = 0; i < k; i++) {
        prob[i] = (count[i] + 1) / n;
    }
    return prob;
}

