        final Set<EvictionListener> evictionListeners;
        synchronized (listeners) {
            evictionListeners = new HashSet<>(listeners);
        }
        decrementRefCount();
        evictionListeners.forEach(eachListener -> eachListener.onEviction(this));
    }
