boolean canPunctuate(final long timestamp) {
    synchronized (pq) {
        PunctuationSchedule top = pq.peek();
        while (top != null && top.timestamp <= timestamp) {
            if (!top.isCancelled()) {
                return true;
            }

            pq.poll();
            top = pq.peek();
        }
        return false;
    }
}

