public static double dot(double[] a, double[] b) {
    if (a.length != b.length) {
        throw new IllegalArgumentException("Arrays have different length.");
    }

    double sum = 0.0;
    for (int i = 0; i < a.length; i++) {
        sum += a[i] * b[i];
    }

    return sum;
}

