public ReleasableLock acquire() throws EngineException {
    lock.lock();
    assert addCurrentThread();
    return this;
}

private boolean addCurrentThread() {
    final Integer current = holdingThreads.get();
    holdingThreads.set(current == null ? 1 : current + 1);
    return true;
}

private long getWrittenOffset() throws IOException {
    return channel.position();
}

private synchronized ReleasableBytesReference pollOpsToWrite() {
    ensureOpen();
    if (this.buffer != null) {
        try (RecyclerBytesStreamOutput toWrite = this.buffer) {
            this.buffer = null;
            this.bufferedBytes = 0;
            return toWrite.moveToBytesReference();
        }
    } else {
        return ReleasableBytesReference.empty();
    }
}

protected final void ensureOpen() {
    if (isClosed()) {
        throw new AlreadyClosedException("translog [" + getGeneration() + "] is already closed", tragedy.get());
    }
}

public ReleasableBytesReference moveToBytesReference() {
    var bytes = bytes();
    var pages = this.pages;
    closeFields();

    return new ReleasableBytesReference(bytes, pages.size() == 1 ? pages.getFirst() : Releasables.wrap(pages));
}

