public double <mask>(int i) {
    int len = Math.min(k, n);
    if (i > len - 1) {
        throw new IllegalArgumentException("HeapSelect i is greater than the number of data received so far.");
    }

    if (i == len-1) {
        return heap[1];
    }

    sort();
    return heap[len-i];
}

children.method_body:
public void sort() {
    if (!sorted) {
        sort(heap, 1, Math.min(k,n));
        sorted = true;
    }
}

private static void sort(double[] a, int l, int r) {
    int h;
    for (h = 1; h <= (r-l)/9; h = 3*h+1);
    for (; h > 0; h /= 3) {
        for (int i = l + h; i <= r; i++) {
            int j = i;
            double v = a[i];
            while (j >= l+h && a[j-h] < v) {
                a[j] = a[j-h];
                j -= h;
                a[j] = v;
            }
        }
    }
}

