public void writeVInt(int i) throws IOException {

    if (Integer.numberOfLeadingZeros(i) >= 25) {
        writeByte((byte) i);
        return;
    }
    byte[] buffer = StreamOutputHelper.getThreadLocalScratchBuffer();
    int index = StreamOutputHelper.putMultiByteVInt(buffer, i, 0);
    writeBytes(buffer, 0, index);
}

private void writePotentiallyNegativeVLong(long value) throws IOException {


    output.writeVLong(Math.max(0, value + 1));
}

public void writeVLong(long i) throws IOException {
    if (i < 0) {
        throw new IllegalStateException("Negative longs unsupported, use writeLong or writeZLong for negative numbers [" + i + "]");
    }
    writeVLongNoCheck(i);
}

