children.method_body:
private int recomputedSize(long bucketOrd) {
    IntArray array = values.get(bucketOrd);
    if (array == null) {
        return 0;
    }
    for (int i = 0; i < array.size(); ++i) {
        final int v = array.get(i);
        if (v == 0) {
            return i;
        }
    }
    return Math.toIntExact(array.size());
}

