public boolean <mask>(T element) {
    if (size < capacity) {
        put(element);
        return true;
    } else if (size > 0 && !lessThan(element, peek())) {
        heap[1] = element;
        adjustTop();
        return true;
    } else {
        return false;
    }
}

children.method_body:
public final void put(T element) {
    size++;
    heap[size] = element;
    upHeap();
}

private void upHeap() {
    int i = size;
    T node = heap[i]; 
    int j = i >>> 1;
    while (j > 0 && lessThan(node, heap[j])) {
        heap[i] = heap[j]; 
        i = j;
        j = j >>> 1;
    }
    heap[i] = node; 
}

private final boolean lessThan(T a, T b) {
    return comparator.compare(a, b) < 0;
}

public final T peek() {
    if (size > 0) {
        return heap[1];
    } else {
        return null;
    }
}

public final void adjustTop() {
    downHeap();
}

private void downHeap() {
    int i = 1;
    T node = heap[i]; 
    int j = i << 1; 
    int k = j + 1;
    if (k <= size && lessThan(heap[k], heap[j])) {
        j = k;
    }

    while (j <= size && lessThan(heap[j], node)) {
        heap[i] = heap[j]; 
        i = j;
        j = i << 1;
        k = j + 1;
        if (k <= size && lessThan(heap[k], heap[j])) {
            j = k;
        }
    }

    heap[i] = node; 
}

