public T root(final T id) {
    T current = id;
    T parent = ids.get(current);

    if (parent == null) {
        throw new NoSuchElementException("id: " + id.toString());
    }

    while (!parent.equals(current)) {

        final T grandparent = ids.get(parent);
        ids.put(current, grandparent);

        current = parent;
        parent = grandparent;
    }
    return current;
}

