                IndexValue<T> indexValue = new IndexValue<>(loadIndex(indexFile.file));
                indexWrapper = indexValue;
                return indexValue.index;
            } else
                throw new IllegalStateException("Unexpected type for indexWrapper " + indexWrapper.getClass());
        } finally {
            lock.unlock();
        }
    }
