    long numValuesLessOrEqual = ExponentialHistogramQuantile.estimateRank(histogram, x, true);
    long numValuesEqual = numValuesLessOrEqual - numValuesLess;

    return (numValuesLess + numValuesEqual / 2.0) / histogram.valueCount();
}

