public void update(long currentTimeMs) {
    this.currentTimeMs = Math.max(currentTimeMs, this.currentTimeMs);
}

public boolean isExpired() {
    return currentTimeMs >= deadlineMs;
}

public long isExpiredBy() {
    return Math.max(0, currentTimeMs - deadlineMs);
}

public String memberId() {
    return memberId;
}

public void maybeRejoinStaleMember() {
    isPollTimerExpired = false;
    if (state == MemberState.STALE) {
        log.debug("Expired poll timer has been reset so stale member {} will rejoin the group " +
            "when it completes releasing its previous assignment.", memberId);
        staleMemberAssignmentRelease.whenComplete((__, error) -> transitionToJoining());
    }
}

public void transitionToJoining() {
    if (state == MemberState.FATAL) {
        log.warn("No action taken to join the group with the updated subscription because " +
                "the member is in FATAL state");
        return;
    }
    if (reconciliationInProgress) {
        rejoinedWhileReconciliationInProgress = true;
    }
    resetEpoch();
    transitionTo(MemberState.JOINING);
    log.debug("Member {} will join the group on the next call to poll.", memberId);
    clearPendingAssignmentsAndLocalNamesCache();
}

public void reset(long timeoutMs) {
    if (timeoutMs < 0)
        throw new IllegalArgumentException("Invalid negative timeout " + timeoutMs);

    this.timeoutMs = timeoutMs;
    this.startMs = this.currentTimeMs;

    if (currentTimeMs > Long.MAX_VALUE - timeoutMs)
        this.deadlineMs = Long.MAX_VALUE;
    else
        this.deadlineMs = currentTimeMs + timeoutMs;
}

