private static int normalize(int codepoint) {
    if (codepoint == TOKEN_START_OR_END_CHAR) {
        return codepoint;
    }
    if (Character.isLetterOrDigit(codepoint) == false) {

        return 47;
    }

    if (codepoint > 48 && codepoint <= 128 && codepoint % 2 == 0) {

        return codepoint - 1;
    } else {

        return codepoint;
    }
}

