public T poll() {
    lock.lock();
    try {
        if (queue.size() == 0) {
            moveToUnAvailable();
            return null;
        }
        return dequeue();
    } finally {
        lock.unlock();
    }
}

@GuardedBy("lock")
private void moveToUnAvailable() {
    if (currentFuture == AVAILABLE) {
        currentFuture = new CompletableFuture<>();
    }
}

@GuardedBy("lock")
private T dequeue() {
    final int sizeBefore = queue.size();
    final T element = queue.poll();
    if (sizeBefore == capacity && !notFull.isEmpty()) {
        signalNextPutter();
    }
    if (queue.isEmpty()) {
        moveToUnAvailable();
    }
    return element;
}

