int <mask>(long epoch) {
    if (epoch == LATEST_EPOCH) {
        return baseSize();
    } else {
        Iterator<Snapshot> iterator = snapshotRegistry.iterator(epoch);
        while (iterator.hasNext()) {
            Snapshot snapshot = iterator.next();
            HashTier<T> tier = snapshot.getDelta(SnapshottableHashTable.this);
            if (tier != null) {
                return tier.size;
            }
        }
        return baseSize();
    }
}

