static ActivationFunction sigmoid() {
    return new ActivationFunction() {
        @Override
        public String name() {
            return "SIGMOID";
        }

        @Override
        public void f(Vector x) {
            int n = x.size();
            for (int i = 0; i < n; i++) {
                x.set(i, MathEx.sigmoid(x.get(i)));
            }
        }

        @Override
        public void g(Vector g, Vector y) {
            int n = y.size();
            for (int i = 0; i < n; i++) {
                double yi =  y.get(i);
                g.mul(i, yi * (1.0 - yi));
            }
        }
    };
}

