public void update(int node) {
    final int prev = prev(node);
    final int next = next(node);
    if ((prev == NIL || compare(prev) > 0) && (next == NIL || compare(next) < 0)) {

        copy(node);
        for (int n = node; n != NIL; n = parent(n)) {
            fixAggregates(n);
        }
    } else {


        remove(node);
        add();
    }
}

public final int prev(int node) {
    final int left = left(node);
    if (left != NIL) {
        return last(left);
    } else {
        int parent = parent(node);
        while (parent != NIL && node == left(parent)) {
            node = parent;
            parent = parent(parent);
        }
        return parent;
    }
}

public final int next(int node) {
    final int right = right(node);
    if (right != NIL) {
        return first(right);
    } else {
        int parent = parent(node);
        while (parent != NIL && node == right(parent)) {
            node = parent;
            parent = parent(parent);
        }
        return parent;
    }
}

public int parent(int node) {
    return parent.get(node);
}

protected void fixAggregates(int node) {
    depth(node, 1 + Math.max(depth(left(node)), depth(right(node))));
}

public void remove(int node) {
    if (node == NIL) {
        throw new IllegalArgumentException();
    }
    if (left(node) != NIL && right(node) != NIL) {

        final int next = next(node);
        assert next != NIL;
        swap(node, next);
    }
    assert left(node) == NIL || right(node) == NIL;

    final int parent = parent(node);
    int child = left(node);
    if (child == NIL) {
        child = right(node);
    }

    if (child == NIL) {

        if (node == root) {
            assert size() == 1 : size();
            root = NIL;
        } else {
            if (node == left(parent)) {
                left(parent, NIL);
            } else {
                assert node == right(parent);
                right(parent, NIL);
            }
        }
    } else {

        if (node == root) {
            assert size() == 2;
            root = child;
        } else if (node == left(parent)) {
            left(parent, child);
        } else {
            assert node == right(parent);
            right(parent, child);
        }
        parent(child, parent);
    }

    release(node);
    rebalance(parent);
}

public boolean add() {
    if (root == NIL) {
        root = nodeAllocator.newNode();
        copy(root);
        fixAggregates(root);
        return true;
    } else {
        int node = root;
        assert parent(root) == NIL;
        int parent;
        int cmp;
        do {
            cmp = compare(node);
            if (cmp < 0) {
                parent = node;
                node = left(node);
            } else if (cmp > 0) {
                parent = node;
                node = right(node);
            } else {
                merge(node);
                return false;
            }
        } while (node != NIL);

        node = nodeAllocator.newNode();
        if (node >= capacity()) {
            resize(oversize(node + 1));
        }
        copy(node);
        parent(node, parent);
        if (cmp < 0) {
            left(parent, node);
        } else {
            right(parent, node);
        }

        rebalance(node);

        return true;
    }
}

