public Builder precision(double meters) {
    int level = GeoUtils.geoHashLevelsForPrecision(meters);

    if (GeoUtils.geoHashCellSize(level) < meters) {
        level = Math.max(1, level - 1);
    }
    return precision(level);
}

public static int geoHashLevelsForPrecision(double meters) {
    assert meters >= 0;

    if (meters == 0) {
        return GEOHASH_MAX_LEVELS_POSSIBLE;
    } else {
        final double ratio = 1 + (EARTH_POLAR_DISTANCE / EARTH_EQUATOR); 
        final double width = Math.sqrt((meters * meters) / (ratio * ratio)); 
        final double part = Math.ceil(EARTH_EQUATOR / width);
        if (part == 1) return 1;
        final int bits = (int) Math.round(Math.ceil(Math.log(part) / Math.log(2)));
        final int full = bits / 5;                
        final int left = bits - full * 5;           
        final int even = full + (left > 0 ? 1 : 0);     
        final int odd = full + (left > 3 ? 1 : 0);      
        return even + odd;
    }
}

public static double geoHashCellSize(int level) {
    assert level >= 0;
    final double w = geoHashCellWidth(level);
    final double h = geoHashCellHeight(level);
    return Math.sqrt(w * w + h * h);
}

public Builder precision(int level) {
    this.precision = level;
    return this;
}

