@Override
public BlockBuilder <mask>(int value)
{
    if (values.length <= positionCount) {
        growCapacity();
    }

    values[positionCount] = (short) value;

    hasNonNullValue = true;
    positionCount++;
    if (blockBuilderStatus != null) {
        blockBuilderStatus.addBytes(Byte.BYTES + Short.BYTES);
    }
