public boolean nextBit()
        throws IOException
{

    if (bitsInData == 0) {
        readByte();
    }


    boolean result = (data & HIGH_BIT_MASK) != 0;


    data <<= 1;
    bitsInData--;

    return result;
}

private void readByte()
        throws IOException
{
    checkState(bitsInData == 0);
    data = byteStream.next();
    bitsInData = 8;
}

