public void <mask>(WeightedDoubleReservoirSample other)
{
    totalPopulationWeight += other.totalPopulationWeight;
    for (int i = 0; i < other.count; i++) {
        addWithAdjustedWeight(other.samples[i], other.weights[i]);
    }
