private static void decode16(int[] docIDs, int half, int min) {
    for (int i = 0; i < half; ++i) {
        final int l = docIDs[i];
        docIDs[i] = (l >>> 16) + min;
        docIDs[i + half] = (l & 0xFFFF) + min;
    }
}

