void flush() {
    if (latestBucketStartMs < 0) {
        return;
    }

    int bucketIndex = earliestBucketIndex;
    while (bucketIndex != latestBucketIndex) {
        flush(bucketIndex);
        bucketIndex = (bucketIndex + 1) % maxSize;
