void <mask>(long bucketOrd, HyperLogLog hll) {
    final LinearCountingCell cell = bucketOrd < cells.size() ? cells.get(bucketOrd) : null;
    if (cell == null) {
        return;
    }
    for (int v : cell.values) {
        if (v != 0) {
            hll.collectEncoded(bucketOrd, v);
        }
    }
    closeCell(cell);
    cells.set(bucketOrd, null);
}

children.method_body:
public void collectEncoded(long bucketOrd, int encoded) {
    final int runLen = decodeRunLen(encoded, p);
    final int index = decodeIndex(encoded, p);
    addRunLen(bucketOrd, index, runLen);
}

static int decodeRunLen(int encoded, int p) {
    if ((encoded & 1) == 1) {
        return (((encoded >>> 1) & 0x3F) + (P2 - p));
    } else {
        final int bits = encoded << (31 + p - P2);
        assert bits != 0;
        return 1 + Integer.numberOfLeadingZeros(bits);
    }
}

static int decodeIndex(int encoded, int p) {
    long index;
    if ((encoded & 1) == 1) {
        index = encoded >>> 7;
    } else {
        index = encoded >>> 1;
    }
    return (int) (index >>> (P2 - p));
}

