    StringBuilder sb = new StringBuilder();
    m = Math.min(m, nrow);
    n = Math.min(n, ncol);

    String newline = n < ncol ? "...\n" : "\n";

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            sb.append(String.format("%8.4f  ", get(i, j)));
