private static long roundUpToPowerOfTwo(long i) {
    if (i <= 0) {
        return 0;
    } else if (i > (1L << 62)) {
        throw new ArithmeticException("There are no 63-bit powers of 2 higher than " +
                "or equal to " + i);
    } else {
        return 1L << -Long.numberOfLeadingZeros(i - 1);
    }
}

