@Override
public void skip(long items)
        throws IOException
{
    if (bitsInData >= items) {
        data <<= items;
        bitsInData -= items;
    }
    else {
        items -= bitsInData;
        bitsInData = 0;

        byteStream.skip(items >>> 3);
        items &= 0b111;

        if (items != 0) {
            readByte();
            data <<= items;
            bitsInData -= items;
        }
    }
}

@Override
public void skip(long items)
        throws IOException
{
    while (items > 0) {
        if (offset == length) {
            readNextBlock();
        }
        long consume = min(items, length - offset);
        offset += consume;
        items -= consume;
    }
}

private void readByte()
        throws IOException
{
    checkState(bitsInData == 0);
    data = byteStream.next();
    bitsInData = 8;
}

