int next(int epoch) {
    if (brokers.isEmpty()) return -1;
    if (this.epoch != epoch) {
        this.epoch = epoch;
        this.index = 0;
        this.offset = (offset + 1) % brokers.size();
    }
    if (index >= brokers.size()) return -1;
    int broker = brokers.get((index + offset) % brokers.size());
    index++;
    return broker;
}

