public static IndexRoutingTable <mask>(StreamInput in) throws IOException {
    Index index = new Index(in);
    Builder builder = new Builder(ShardRoutingRoleStrategy.NO_SHARD_CREATION, index);

    int size = in.readVInt();
    builder.ensureShardArray(size);
    for (int i = 0; i < size; i++) {
        builder.addIndexShard(IndexShardRoutingTable.Builder.readFromThin(in, index));
    }

    return builder.build();
}

children.method_body:
public int readVInt() throws IOException {
    return readVIntSlow();
}

protected final int readVIntSlow() throws IOException {
    byte b = readByte();
    int i = b & 0x7F;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7F) << 7;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7F) << 14;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7F) << 21;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    if ((b & 0x80) != 0) {
        throwOnBrokenVInt(b, i);
    }
    return i | ((b & 0x7F) << 28);
}

public void ensureShardArray(int shardCount) {
    if (shards == null) {
        shards = new IndexShardRoutingTable.Builder[shardCount];
    } else if (shards.length < shardCount) {
        IndexShardRoutingTable.Builder[] updated = new IndexShardRoutingTable.Builder[shardCount];
        System.arraycopy(shards, 0, updated, 0, shards.length);
        shards = updated;
    }
}

public IndexRoutingTable build() {
    final IndexShardRoutingTable[] res;
    if (shards != null) {
        res = new IndexShardRoutingTable[shards.length];
        for (int i = 0; i < shards.length; i++) {
            res[i] = shards[i].build();
        }
    } else {
        res = new IndexShardRoutingTable[0];
    }
    return new IndexRoutingTable(index, res);
}

public IndexShardRoutingTable build() {

    assert distinctNodes(shards) : "more than one shard with same id assigned to same node (shards: " + shards + ")";
    assert noDuplicatePrimary(shards) : "expected but did not find unique primary in shard routing table: " + shards;
    assert noAssignedReplicaWithoutActivePrimary(shards) : "unexpected assigned replica with no active primary: " + shards;
    return new IndexShardRoutingTable(shardId, shards);
}

