private static int <mask>(
        MemorySegment segment, int offset, int lengthInBytes, int seed) {
    assert (lengthInBytes % 4 == 0);
    int h1 = seed;
    for (int i = 0; i < lengthInBytes; i += 4) {
        int halfWord = segment.getInt(offset + i);
        int k1 = mixK1(halfWord);
        h1 = mixH1(h1, k1);
    }
    return h1;
}

