@Override
public double[] kg(double dist) {
    double[] g = new double[2];
    double d = dist / sigma;
    double k = Math.exp(-d);
    g[0] = k;
    g[1] = k * d / sigma;
    return g;
}

public static double distance(double[] a, double[] b) {
    return sqrt(squaredDistance(a, b));
}

public static double squaredDistance(double[] a, double[] b) {
    if (a.length != b.length) {
        throw new IllegalArgumentException("Input vector sizes are different.");
    }

    switch (a.length) {
        case 2: {
            double d0 = a[0] - b[0];
            double d1 = a[1] - b[1];
            return d0 * d0 + d1 * d1;
        }

        case 3: {
            double d0 = a[0] - b[0];
            double d1 = a[1] - b[1];
            double d2 = a[2] - b[2];
            return d0 * d0 + d1 * d1 + d2 * d2;
        }

        case 4: {
            double d0 = a[0] - b[0];
            double d1 = a[1] - b[1];
            double d2 = a[2] - b[2];
            double d3 = a[3] - b[3];
            return d0 * d0 + d1 * d1 + d2 * d2 + d3 * d3;
        }
    }

    double sum = 0.0;
    for (int i = 0; i < a.length; i++) {
        double d = a[i] - b[i];
        sum += d * d;
    }

    return sum;
}

