private int <mask>(String word, int last) {
    int i = 0;
    if ((i < last) && (!(vowel(word.charAt(i), 'a')))) {
        i++;
    }

    if (i != 0) {
        while ((i < last) && (!(vowel(word.charAt(i), word.charAt(i - 1))))) {
            i++;
        }
    }

    return Math.min(i, last);
}

