private boolean vowel(char ch, char prev) {
    return switch (ch) {
        case 'a', 'e', 'i', 'o', 'u' -> true;
        case 'y' -> switch (prev) {
            case 'a', 'e', 'i', 'o', 'u' -> false;
            default -> true;
        };
        default -> false;
    };
}

