public static <K> Windowed<K> <mask>(final byte[] binaryKey,
                                           final long windowSize,
                                           final Deserializer<K> deserializer,
                                           final String topic) {
    final K key = deserializer.deserialize(topic, extractStoreKeyBytes(binaryKey));
