}

public Class<?> type() {
    Type type = Types.getBaseClass(getClass(), ConsoleAnnotatorFactory.class);
    if (type instanceof ParameterizedType)
        return Types.erasure(Types.getTypeArgument(type, 0));
    else
        return Object.class;
}

