private NetworkClientDelegate.UnsentRequest makeHeartbeatRequest(final long currentTimeMs, final boolean ignoreResponse) {
    NetworkClientDelegate.UnsentRequest request = makeHeartbeatRequest(ignoreResponse);
    heartbeatRequestState.onSendAttempt(currentTimeMs);
    membershipManager().onHeartbeatRequestGenerated();
    metricsManager.recordHeartbeatSentMs(currentTimeMs);
    heartbeatRequestState.resetTimer();
    return request;
}

@SuppressWarnings("unchecked")
private NetworkClientDelegate.UnsentRequest makeHeartbeatRequest(final boolean ignoreResponse) {
    NetworkClientDelegate.UnsentRequest request = buildHeartbeatRequest();
    if (ignoreResponse)
        return logResponse(request);
    else
        return request.whenComplete((response, exception) -> {
            long completionTimeMs = request.handler().completionTimeMs();
            if (response != null) {
                metricsManager.recordRequestLatency(response.requestLatencyMs());
                onResponse((R) response.responseBody(), completionTimeMs);
            } else {
                onFailure(exception, completionTimeMs);
            }
        });
}

public void onSendAttempt(final long currentTimeMs) {
    this.requestInFlight = true;


    this.lastSentMs = currentTimeMs;
}

public void onHeartbeatRequestGenerated() {
    MemberState state = state();
    if (state == MemberState.ACKNOWLEDGING) {
        if (targetAssignmentReconciled()) {
            transitionTo(MemberState.STABLE);
        } else {
            log.debug("Member {} with epoch {} transitioned to {} after a heartbeat was sent " +
                    "to ack a previous reconciliation. \n" +
                    "\t\tCurrent assignment: {} \n" +
                    "\t\tTarget assignment: {}\n",
                    memberId, memberEpoch, MemberState.RECONCILING, currentAssignment, currentTargetAssignment);
            transitionTo(MemberState.RECONCILING);
        }
    } else if (state == MemberState.LEAVING) {
        if (isPollTimerExpired) {
            log.debug("Member {} with epoch {} generated the heartbeat to leave due to expired poll timer. It will " +
                "remain stale (no heartbeat) until it rejoins the group on the next consumer " +
                "poll.", memberId, memberEpoch);
            transitionToStale();
        } else {
            log.debug("Member {} with epoch {} generated the heartbeat to leave the group.", memberId, memberEpoch);
            transitionTo(MemberState.UNSUBSCRIBED);
        }
    }
}

