protected final long readVLongSlow() throws IOException {
    byte b = readByte();
    long i = b & 0x7FL;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7FL) << 7;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7FL) << 14;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7FL) << 21;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7FL) << 28;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7FL) << 35;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7FL) << 42;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= (b & 0x7FL) << 49;
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    i |= ((b & 0x7FL) << 56);
    if ((b & 0x80) == 0) {
        return i;
    }
    b = readByte();
    if (b != 0 && b != 1) {
        throwOnBrokenVLong(b, i);
    }
    i |= ((long) b) << 63;
    return i;
}

