private void createBooleanOutputStream()
{
    checkState(booleanOutputStream == null);
    booleanOutputStream = new BooleanOutputStream(buffer);
    for (int groupsCount : groupsCounts) {
        booleanOutputStream.writeBooleans(groupsCount, true);
        booleanOutputStream.recordCheckpoint();
    }
    booleanOutputStream.writeBooleans(currentGroupCount, true);
}

public void writeBooleans(int count, boolean value)
{
    if (count == 0) {
        return;
    }

    checkArgument(count > 0, "count must be positive");

    if (bitsInData != 0) {
        int bitsToWrite = Math.min(count, 8 - bitsInData);
        if (value) {
            data |= getLowBitMask(bitsToWrite) << (8 - bitsInData - bitsToWrite);
        }

        bitsInData += bitsToWrite;
        if (bitsInData != 8) {

            return;
        }

        count -= bitsToWrite;
        flushData();
    }



    while (count >= 8) {
        if (value) {
            byteOutputStream.writeByte((byte) 0b1111_1111);
        }
        else {
            byteOutputStream.writeByte((byte) 0b0000_0000);
        }
        count -= 8;
    }


    if (count > 0) {
        if (value) {
            data = getLowBitMask(count) << (8 - count);
        }
        bitsInData = count;
    }
}

@Override
public void recordCheckpoint()
{
    checkState(!closed);
    byteOutputStream.recordCheckpoint();
    checkpointBitOffsets.add(bitsInData);
}

