public double[] <mask>(double x) {
    int k = components.length;
    double[] prob = new double[k];
    for (int i = 0; i < k; i++) {
        Component c = components[i];
        prob[i] = c.priori * c.distribution.p(x);
    }

    double p = MathEx.sum(prob);
    for (int i = 0; i < k; i++) {
        prob[i] /= p;
    }
    return prob;
}

