static void siftDown(int[] a, int k, int n) {
    while (2*k <= n) {
        int j = 2 * k;
        if (j < n && a[j] < a[j + 1]) {
            j++;
        }
        if (a[k] >= a[j]) {
            break;
        }
        swap(a, k, j);
        k = j;
    }
}

static void swap(int[] a, int i, int j) {
    int temp = a[i];
    a[i] = a[j];
    a[j] = temp;
}

