public static <T extends Comparable<? super T>> T <mask>(T[] x) {
    return QuickSelect.q3(x);
}

children.method_body:
static <T extends Comparable<? super T>> T q3(T[] x) {
    int k = 3 * x.length / 4;
    return select(x, k);
}

static <T extends Comparable<? super T>> T select(T[] x, int k) {
    int n = x.length;
    int l = 0;
    int ir = n - 1;

    T a;
    int i, j, mid;
    for (;;) {
        if (ir <= l + 1) {
            if (ir == l + 1 && x[ir].compareTo(x[l]) < 0) {
                Sort.swap(x, l, ir);
            }
            return x[k];
        } else {
            mid = (l + ir) >> 1;
            Sort.swap(x, mid, l + 1);
            if (x[l].compareTo(x[ir]) > 0) {
                Sort.swap(x, l, ir);
            }
            if (x[l + 1].compareTo(x[ir]) > 0) {
                Sort.swap(x, l + 1, ir);
            }
            if (x[l].compareTo(x[l + 1]) > 0) {
                Sort.swap(x, l, l + 1);
            }
            i = l + 1;
            j = ir;
            a = x[l + 1];
            for (;;) {
                do {
                    i++;
                } while (x[i].compareTo(a) < 0);
                do {
                    j--;
                } while (x[j].compareTo(a) > 0);
                if (j < i) {
                    break;
                }
                Sort.swap(x, i, j);
            }
            x[l + 1] = x[j];
            x[j] = a;
            if (j >= k) {
                ir = j - 1;
            }
            if (j <= k) {
                l = i;
            }
        }
    }
}

