                                    || !sessionsTable
                                            .getSelectionModel()
                                            .isSelectedIndex(row)) {
                                sessionsTable.getSelectionModel().clearSelection();
                                if (row >= 0) {
                                    sessionsTable
                                            .getSelectionModel()
                                            .setSelectionInterval(row, row);
                                }
                            }

                            View.getSingleton()
                                    .getPopupMenu()
                                    .show(e.getComponent(), e.getX(), e.getY());
                        }
                    }
                });
