void <mask>(Consumer<Releasable> task) {
    if (semaphore.tryAcquire()) {
        executeAndRelease(task);
    } else {
        queue.add(task);
        if (semaphore.tryAcquire()) {
            task = pollNextTaskOrReleasePermit();
            if (task != null) {
                executeAndRelease(task);
            }
        }
    }
}

