private Consumer<Releasable> pollNextTaskOrReleasePermit() {
    var task = queue.poll();
    if (task == null) {
        semaphore.release();
        while (queue.peek() != null && semaphore.tryAcquire()) {
            task = queue.poll();
            if (task == null) {
                semaphore.release();
            } else {
                return task;
            }
        }
    }
    return task;
}

