protected int search(double x) {
    return cor ? hunt(x) : locate(x);
}

private int hunt(double x) {
    int jl = jsav, jm, ju, inc = 1;

    boolean ascnd = (xx[n - 1] >= xx[0]);

    if (jl < 0 || jl > n - 1) {
        jl = 0;
        ju = n - 1;
    } else {
        if (x >= xx[jl] == ascnd) {
            for (;;) {
                ju = jl + inc;
                if (ju >= n - 1) {
                    ju = n - 1;
                    break;
                } else if (x < xx[ju] == ascnd) {
                    break;
                } else {
                    jl = ju;
                    inc += inc;
                }
            }
        } else {
            ju = jl;
            for (;;) {
                jl = jl - inc;
                if (jl <= 0) {
                    jl = 0;
                    break;
                } else if (x >= xx[jl] == ascnd) {
                    break;
                } else {
                    ju = jl;
                    inc += inc;
                }
            }
        }
    }

    while (ju - jl > 1) {
        jm = (ju + jl) >> 1;
        if (x >= xx[jm] == ascnd) {
            jl = jm;
        } else {
            ju = jm;
        }
    }

    cor = Math.abs(jl - jsav) <= dj;
    jsav = jl;
    return Math.max(0, Math.min(n - 2, jl));
}

private int locate(double x) {
    int ju, jm, jl;

    boolean ascnd = (xx[n - 1] >= xx[0]);

    jl = 0;
    ju = n - 1;
    while (ju - jl > 1) {
        jm = (ju + jl) >> 1;
        if (x >= xx[jm] == ascnd) {
            jl = jm;
        } else {
            ju = jm;
        }
    }

    cor = Math.abs(jl - jsav) <= dj;
    jsav = jl;

    return Math.max(0, Math.min(n - 2, jl));
}

