public long readVarint(boolean signed)
        throws IOException
{
    long result = 0;
    int shift = 0;
    int available = available();
    if (available >= 2 * Long.BYTES) {
        long word = ByteArrays.getLong(buffer, position);
        int count = 1;
        boolean atEnd = false;
        result = word & 0x7f;
        if ((word & 0x80) != 0) {
            long control = word >>> 8;
            long mask = 0x7f << 7;
            while (true) {
                word = word >>> 1;
                result |= word & mask;
                count++;
                if ((control & 0x80) == 0) {
                    atEnd = true;
                    break;
                }
                if (mask == 0x7fL << (7 * 7)) {
                    break;
                }
                mask = mask << 7;
                control = control >>> 8;
            }
            if (!atEnd) {
                word = ByteArrays.getLong(buffer, position + 8);
                result |= (word & 0x7f) << 56;
                if ((word & 0x80) == 0) {
                    count++;
                }
                else {
                    result |= 1L << 63;
                    count += 2;
                }
            }
        }
        position += count;
    }
    else {
        do {
            if (available == 0) {
                advance();
                available = available();
                if (available == 0) {
                    throw new OrcCorruptionException(orcDataSourceId, "End of stream in RLE Integer");
                }
            }
            available--;
            result |= (long) (buffer[position] & 0x7f) << shift;
            shift += 7;
        }
        while ((buffer[position++] & 0x80) != 0);
    }
    if (signed) {
        return zigzagDecode(result);
    }
    else {
        return result;
    }
}

