public CompletableFuture<Void> closeAsync() {
    synchronized (lock) {
        if (isRunning()) {
            terminationFuture =
                    FutureUtils.orTimeout(
                            asyncWaitForResultsToBeAccessed(),
                            cacheDuration.getSeconds(),
                            TimeUnit.SECONDS,
