public static void shutdownAll() {
    final List<BatchQueue<?>> allQueues = new ArrayList<>(QUEUES.values());
    QUEUES.clear();

    for (final BatchQueue<?> queue : allQueues) {
        try {
            queue.shutdown();
        } catch (final Throwable t) {
            log.error("Error shutting down queue: {}", queue.getName(), t);
        }
    }
}

void shutdown() {
    running = false;

    final ArrayBlockingQueue<T>[] currentPartitions = this.partitions;
    final List<T> combined = new ArrayList<>();
    for (final ArrayBlockingQueue<T> partition : currentPartitions) {
        partition.drainTo(combined);
    }
    if (!combined.isEmpty()) {

        dispatch(combined, -1, null);
    }
    scheduler.shutdown();
}

