@Override
public int nextInt(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    }


    if ((n & -n) == n) {
        return (int) ((n * (long) next(31)) >> 31);
    }

    int bits, val;
    do {
        bits = next(31);
        val = bits % n;
    } while (bits - val + (n - 1) < 0);

    return val;
}

public static void swap(int[] x, int i, int j) {
    int s = x[i];
    x[i] = x[j];
    x[j] = s;
}

